    "descriptionKh": "រមណីយដ្ឋានកែឆ្នៃមួយនាស្រុកសំឡូត ដែលទាក់ទាញទេសចរមកពីជិតឆ្ងាយនោះ ទំនងជាធ្វើឱ្យយើងទាយថាទីនេះច្បាស់ជាសម្បូរទៅដោយដើមគ្រញូងមិនខាននោះទេ។ គេបានតំណាលថា កាលពីមុនមានគល់គ្រញូងងាប់ដ៏ធំមួយដើមធ្លាក់អណ្ដែតតាមទឹកស្ទឹងពីតំបន់ព្រៃភ្នំខាងលើ ហើយក៏មកទើរនៅទីនេះក៏ដោយសារតែមានផ្ទាំងថ្មច្រូងច្រាងជាច្រើន ទើបក្រោយមកអ្នកភូមិក៏ប្រសិទ្ធនាមថាស្ទឹងគ្រញូងតរៀងមក។ ស្ទឹងគ្រញូងប្រកបដោយវិសាលភាពធំធេងអមដោយផ្ទៃដីមានដើមឈើទាំងតូចធំដុះចម្រុះគ្នាជាអន្លើៗចោលម្លប់ដ៏ត្រឈឹងត្រឈៃលើផ្ទៃដី ៥ ហិកតា នៅជាប់នឹងមាត់ស្ទឹងដែលមានចរន្តទឹកហូរខួបប្រាំងខួបវស្សា។ ទេសចរក៏អាចចុះងូតទឹកលេងកម្សាន្តក្នុងស្ទឹងមានថ្មរដិបរដុបផុសឡើងរាយប៉ាយ។ ម្ចាស់រមណីយដ្ឋានរៀបរាប់ថា កាលពីមុននៅទីនេះជាទីវាលមានព្រៃដូចសព្វថ្ងៃនិងស្ទឹងតែផ្លូវចូលមានការលំបាកធ្វើដំណើរមកកម្សាន្តជាកម្មសិទ្ធិរបស់រដ្ឋ។ ចាប់តាំងពីឆ្នាំ ២០១៥ មកគាត់ទទួលបាននូវសិទ្ធិជួលពីអាជ្ញាធរតំបន់ ហើយក៏បានជួយកសាងផ្លូវក្រាលក្រួសក្រហមមួយខ្សែនេះរួចបានកែខៃឱ្យក្លាយជាទីកន្លែងកម្សាន្តមួយដ៏ល្បី។",
    "descriptionEn": "A recycling station in the district of Samlot which attracts tourists from here and elsewhere suggests that this place must be rich in rosewood. It is said that in the past, a big dead rosewood fell floating in the river from the upper forest area and also came here because there are many rocks, then the villagers later named it Stung Kronhong, respectively . Stung Kronhoung is a large area, accompanied by a large area of ​​trees, large and small, growing intermittently, leaving deep shadow in an area of ​​5 hectares, beside the river, which has a stream of water at dry birthday. Tourists can also bathe in the river with rocks. The station owner described that in the past it was a field with forests like today and rivers, but the access road was difficult to navigate to visit the state-owned station. Since 2015, he received a lease from the local authority and also participated in the construction of this red gravel road and turned it into a famous entertainment venue.",
