    "descriptionEn": "Compared with similar types of recreation areas, such as Phnom Preav Valley, on the other side of the waterfall, the mango plantation has a larger yard, and the water play area is larger, and the water is shallower. These are the reasons why this recycling station is the most famous in the region. The mango plantation across the river has a longer, quieter waterfront.",
