    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តក្ដុលឬវត្តប្រាប្បច្ចាមិត្របានកសាងឡើងតាំងពីឆ្នាំ ១៨៤៥ ដោយលោកឧញ្ញាបឌិន ដោយហេតុថា ទីនោះធ្លាប់ជាទីលានកន្លែងហ្វឹកហាត់ទ័ព។ ឧកញ្ញាបដិនបានធ្វើពាក្យសច្ចាថាបើកាលណាធ្វើសឹកឈ្នះសត្រូវនឹងយកទីលានហ្វឹកហាត់ទ័ពនេះកសាងជាវត្ត។ សេចក្ដីប្រាថ្នារបស់លោកក៏បានសំរេច ទើបលោកធ្វើតាមពាក្យសច្ចា។ ចំណែការហៅថា វត្តក្ដុល ដោយយកឈ្មោះតាមព្រែក ហើយពីដើមមានដើមក្ដុលដុះនៅតាមដងព្រែកជាច្រើន។ នៅសម័យកម្ពុជាប្រជាធិបតេយ្យព្រះសង្ឃត្រូវបានផ្សឹកទាំងអស់ ហើយវត្តនេះបាលក្លាយជាទីលានហាលស្រូវ បញ្ជាន់ស្រូវ ជង្រុកស្រូវ និងរោងជាងដេរ។ ចំណែកសមិទ្ធិផលក្នុងវត្តមួយចំនួនក៏ត្រូវបានបំផ្លាញ។ លុះក្រោយថ្ងៃ៧មករាទើបវត្តត្រូវបានកសាងឡើងវិញ។",
    "descriptionEn": "Wat Kdol or Wat Prachaphamit was built in 1845 by Mr. Onha Din because it was once a military training ground. Oknha Paden swore that if he fought and defeated the enemy, he would use this training ground as a pagoda. His wish came true and he obeyed. The name is called Wat Kdol after the name of the canal, and originally many Kdol trees grew along the stream. During the era of Democratic Kampuchea, all the monks were beheaded, and this pagoda became a place of rice drying, rice threshing and barns. Some achievements of the pagoda were also destroyed. It was not until January 7 that the pagoda was rebuilt.",
