    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "ដើមឡើយវត្តពោធិ៍វាល គឺជាវាលស្រែមួយតែប៉ុណ្ណោះ ហើយនៅកណ្ដាលវាលស្រែ មានដើមពោធិ៍ដ៏ធំមួយ និងយប់ឡើងកាលណាតែងមានពន្លឺចេញពីដើមពោធិ៍នោះ។ បន្ទាប់ពីបានឃើញពន្លឺនោះមក ពុទ្ធបរិស័ទក៏បានមូលមតិគ្នាជីកដីក្រោមដើមពោធិ៍នោះ ក៏ប្រទះឃើញពុទ្ធបដិមា ១អង្គ ហើយក៏មានជំនឿតៗគ្នា រហូតដល់បង្កើតទីអាស្រមសម្រាប់គោរពបូជា។ ដើមពោធិ៍នោះងាប់អំឡុងឆ្នាំ ២០១០ ហើយមានដុះកូនដើមពោធិ៍វិញផងដែរ។ វត្តពោធិ៍វាល ត្រូវបានចាប់ផ្ដើមកសាងឡើងនៅអំឡុងឆ្នាំ ១៩៥១ មានឈ្មោះតាម ដើមពោធិ៍កណ្ដាលវាលស្រែនោះ។ ភាពល្បីល្បាញមួយទៀតរបស់បស់វត្តនេះ គឺក្នុងទីវត្តធ្លាប់មានសារមន្ទីរដែលមានសមុច្ច័យជាច្រើន (៣៨រូប) បានត្រូវបាត់បង់ក្នុងសម័យសង្គ្រាមស៊ីវិល ដែលធ្លាប់បានកត់ត្រាដោយសាលាបារាំងចុងបូព៌ា។",
    "descriptionEn": "Originally, Po Veal Pagoda was just a paddy field, and in the middle of the paddy field, there was a big Po tree, and at night, there was always light coming out of this Po tree. After seeing this light, the Buddhists agreed to dig the ground under the Po tree, found a Buddha statue, and believed in each other until they established a hermitage for worship. The Po tree died in 2010 and the Po tree has grown back. Po Veal Pagoda began to be built in 1951, named after the Po tree in the middle of the field. Another famous feature of this pagoda is that in the pagoda there was a museum with many collections (38 people) lost during the civil war, which was recorded by the French School of the Far East.",
    "photoUrl": "https://raw.githubusercontent.com/igpubinfo-max/Khmer-Food-Tourism/8d322f9/public/destinations/rac-k15044.jpg",
