    "nameEn": "Sangke Pagoda (Battambong)",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តឥន្ទ្រាធិបតីឬវត្តសង្កែ ត្រូវបានផ្ដើមកសាងឡើងដោយលោកកឋាថន ញ៉ុញ ឬលោកម្ចាស់ព្រះកោដ្ឋ ដែលត្រូវជាឪពុកចៅពញា កឋាថន ឈុំ ក្នុងទសវត្សរ៍ឆ្នាំ១៩០០។ ស្ថាបត្យកម្មនៃព្រះវិហារ គឺជាប្រភេទសំណង់កម្រនិងជួប ព្រមទាំងព្រះអង្គជីវ៍ ដែលមានបារមីខ្លាំងពូកែ។ នៅសម័យខ្មែរក្រហម គេបានយកព្រះវិហារវត្តសង្កែនេះជាឃ្លាំងដាក់គ្រាប់រំសេវ ទើបនៅចុងខែធ្នូ ឆ្នាំ១៩៧៨ យន្តហោះបានទំលាក់គ្រាប់លើព្រះវិហារនោះធ្វើឱ្យឆេះ និងខូចខាតទាំងស្រុង ប៉ុន្តែព្រះអង្គជីវ៍ ក្នុងព្រះវិហារមិនខូចខាតអ្វីឡើយ។ នៅឆ្នាំ១៩៩៣ ទើបគេបានកសាងព្រះវិហារថ្មីលើទីតាំងខឿននៃព្រះវិហារចាស់ដដែល និងកំពុងបន្តកសាងបន្ថែមនូវសំណង់ផ្សេងៗ ដើម្បីអូសទាញភ្ញៀវទេសចរណ៍ជាតិនិងអន្តរជាតិ។ នៅប៉ែកខាងកើតព្រះវិហារមានសេសសល់ចេតីយ២ ដែលបានបន្សល់ទុកចំណារថាជាចេតិយសែស្រឡាយ កឋាថនឈុំ កាលពីសម័យមុនៗ។",
    "descriptionEn": "Indrathipadi Pagoda or Sangke Pagoda was established by Mr. Katathon Nhonh or Lord Preah Koth who was the father of King Thorn Chhum in the 1900s. The architecture of the church is a rare type of construction as well as the living beings who have great power. During the Khmer Rouge era, the Pagoda Sangke temple was used as an ammunition depot, but in late December 1978, planes dropped bombs on the temple, set it on fire and completely destroyed it, but the monks at the interior of the temple were not damaged. It was not until 1993 that a new church was built on the site of the old church, and other buildings were constructed to attract domestic and international tourists. On the east side of the temple, there are two stupas left, which are marked as Katathon Chhum dynasty stupas in the past.",
