    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តគរ ជាវត្តដែលមានប្រវត្តិយូរលង់ ហើយជាវត្តដែលត្រូវបានចាត់ទុកជាវត្តទេសចរណ៍ផងដែរ។ វត្តនេះត្រូវបានកសាងឡើងតាំងពី ព.ស ២៤៥៧ ដោយឧបាសក តូច និងឧបាសិកា យិប រួមនិងយាយ ផែ ដែលជាម្ចាស់កម្មសិទ្ធិដីនោះ ព្រមទងការជ្រោមជ្រែងពីសំណាក់ពុទ្ធបរិស័ទជាច្រើន។ ឈ្មោះវត្តនេះមកពីកាលគេកសាងដំបូងនៅទីនោះមានគំនរថ្ម និងឥដ្ឋ ជាច្រើន។ ព្រះវិហារជាប្រភេទព្រះវិហារជហ្វា៦ មានស្លាបដំបូល ២ជាន់ រចនាជាហោជាងលយ។ ព្រះវិហារវត្តនេះ មានចម្លាក់ឈើទិបទមាស ចំណែកហោជាងវិញ ធ្វើពីឈើបិទកញ្ចក់សំណ។ ជញ្ជាំងព្រះវិហារមានគំនូរបុរាណដែលគូរនៅឆ្នាំ ១៩៤៧ និងឆ្នាំ ១៩៥៤។",
    "descriptionEn": "Wat Kor is a pagoda with a long history and is also considered a tourist pagoda. This pagoda was built in 2457 by layman Toch and apprentice Yib and port owner Yeay Phe, with the support of many Buddhists. The name of this pagoda comes from its construction, there are many piles of stones and bricks. Preah Vihear is a type of 6 Javanese temples with two roof wings, designed as a bell tower. The pagoda has wooden carvings, while the craftsman is made of leaded glass. The church walls have old paintings from 1947 and 1954.",
