    "id": "rac-k15047",
    "nameKh": "វត្តកំផែង, វត្តបាការនិវេសន៍",
    "nameEn": "Kampheng Pagoda",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តកំផែងមានអាយុកាលលើសពី ១០០ឆ្នាំ មកហើយ។ នៅក្នុងរជ្ជកាលព្រះបាទស៊ីសុវត្ថិវត្តបានជួសជុលចំនួនពីរលើក ហើយលើកទីបីនៅឆ្នាំ១៩៩៨។ ទេសចរអាចទៅទស្សនាទីនោះដោយងាយព្រោះស្ថិតនៅក្នុងក្រុង។ ពីដើមវត្តនេះ មានទីតាំងចាប់ពីផ្លូវលេខបីទៅកើត ប៉ុន្តែដោយត្រូវសាងសង់ផ្លូវលេខបីទើបត្រូវផ្លាស់ទីតាំងមកខាងលិចផ្លូវលេខបីវិញ។ វត្តកំផែងកកើតឡើងដោយសារពុទ្ធបរិស័ទពិបាកឆ្លងស្ទឹងសង្កែ ទើបសំរេចបង្កើតវត្តនេះឡើង។ វត្តមានទីធ្លាធំទូលាយមានទេសភាពនិងសួនច្បារ ដែលរៀបចំឡើងមានរបៀបរៀបរយ។ អគារនីមួយៗតុបតែងដោយក្បូរក្បាច់រចនាខ្មែរ ព្រមទាំងមានអគារពីរជាន់សម្រាប់តំកល់ព្រះអរហន្តធាតុនិងបេតិភណ្ឌជាតិ។ ភាពល្បីល្បាញមួយទៀតនៃវត្តនេះក្នុងអារម្មណ៍ប្រជាជនខ្មែរតាមអត្ថន័យបទចម្រៀង «ស្ពានឈើអភ័ព្វ» ដែលរៀបរាប់ពីវត្តនេះ។",
    "descriptionEn": "Kampheng Pagoda is over 100 years old. During the reign of King Sisovat, the pagoda was renovated twice and the third time in 1998. Tourists can easily visit it as it is in the city. Originally, this pagoda was located from 3 Street to the East, but due to the construction of 3 Street, it was moved to the West of 3 Street. Kampheng Pagoda was built because that it was difficult for Buddhists to cross the Sangker River, so they decided to build this pagoda. There is a large courtyard with a view and a well-organized garden. Each building is decorated with Khmer motifs and has a two-story building to store artifacts and national heritage. Another famous of this pagoda in the feelings of the Cambodian people in the meaning of the song \"Unfortunate wooden bridge\" which describes this pagoda.",
