    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តដំរីសឬវត្តស្វេតឆត្រ័កុញ្ជរ គឺជាអារាមមួយដែលមានវ័យចំណាស់ហើយត្រូវបានចាត់ជាវត្តទេសចរណ៍គំរូក្នុងខេត្ត។ តាមឈ្មោះជាភាសាបាលី មានន័យថា ដំរីមានឆ័ត្រស ដែលតាមឯកសាររបស់លោក តូច ឈួង វត្តនេះត្រូវបានកសាងឡើងដោយលោកស្រី អ៊ឹង ដែលជាលោកជំទាវធំទី២របស់លោក កថាថន ឈុំ។ ដោយសារកើតទុក្ខនឹងប្ដីមានប្រពន្ធច្រើនលោកស្រីអ៊ឹងមានជំងីធ្ងន់ ទើបលោកស្រីបានទៅបែរបន់ព្រះអង្គខ្មៅនៅវត្តកណ្ដឹងថា បើលោកស្រីជាពីជំងឺនឹងកសាងព្រះវិហារមួយខ្នងនៅវត្តដំរីសថ្វាយ។ បន្ទាប់ពីសះស្បើយពីជំងី លោកស្រីក៏សាងសង់ព្រះវិហារវត្តដំរីសនេះឡើងនៅឆ្នាំ១៩០៤។",
    "descriptionEn": "Wat Domrei sor or Wat Svet Chhat Kunchor is an ancient temple and is considered a model tourist pagoda in the province. The name in Pali means an elephant with a white umbrella, which according to the documents of Mr. Toch Chhuong, this pagoda was built by Mrs. Ung, the second farm of Mr. Katathon Chhum. Due to the grief of her husband and wife, Mrs. Ung was seriously ill, so she turned to Preah Ang Khmao at Wat Kandeung and said that if she recovered from her illness, she would build a temple at Wat Damrei Out. After recovering from her illness, she built the Damrei Sor Pagoda in 1904.",
