    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តពិភិទ្ធារាមគឺជាវត្តដ៏ចំណាស់មួយក្នុងចំណោមវត្តនានាក្នុងខេត្តបាត់ដំបង។ វត្តពិភិទ្ធារាមនេះ បានកសាងឡើងក្នុងឆ្នាំ១៨៧៣ លើទឹកដីរបស់ តារស់ ដែលគាត់បានប្រគេនដល់សង្ឃ។ ពាក្យថា ពិភិទ្ធ គឺជាងារបស់តារស់ជាម្ចាស់ដីនាសម័យនោះ ដូច្នេះអ្នកភូមិក៏ហៅវត្តពិភិទ្ធារាមតាមងារបស់គាត់រៀងមក។ នៅចំកណ្ដាលមាន ព្រះវិហារឈើមួយដ៏ធំស្កឹមស្កៃកសាងនៅ គ.ស.១៨៨៨ ហើយក្នុងទីវត្តក៏មានសំណង់ដទៃៗទៀតផងដែរ។ ក្នុងសម័យសង្គ្រាមស៊ីវិលសមិទិ្ធផលផ្សេងៗត្រូវបានបំផ្លិចបំផ្លាញ ហើយទីនេះជាកន្លែងចិញ្ចឹមជ្រូក។",
    "descriptionEn": "Pipithearam Pagoda is one of the oldest pagodas in Battambang Province. Pipithearam Pagoda was built in 1873 on the territory of Ta Ros, which he gave to the monks. The word Piphit was the title of Ta Ros, the owner of the land at that time, so the villagers called Pagoda Pipithea Ream after him. In the center is a huge wooden temple built in 1888, and in the pagoda there are other buildings. During the Civil War, various achievements were destroyed, and this is where the pigs were bred.",
