    "descriptionKh": "នៅខាងលិចទីក្រុងបាត់ដំបង ចម្ងាយប្រមាណ ១២ គីឡូម៉ែត្រ មានភ្នំជាច្រើននៅជិតៗគ្នា មានភ្នំសំពៅ ភ្នំទ្រុងមាន់-ទ្រុងទា និងភ្នំរំសាយសក់ជាដើម។ ភ្នំសំពៅ គឺជាភ្នំមួយដែលមានកម្ពស់១០០ម៉ែត្រ និងជាទីរមណីយដ្ឋានធម្មជាតិមួយ ដែលភ្ញៀវទេសចរណ៍និយមទៅកម្សាន្ត លំហែនៅចុងសប្ដាហ៍និងពេលមានពិធីបុណ្យទានម្ដងៗ ជាពិសេសនៅក្នុងពិធីបុណ្យចូលឆ្នាំថ្មីប្រពៃណីជាតិខ្មែរ និងពិធីបុណ្យភ្ជុំបិណ្ឌ។ ភ្នំនេះមានទ្រង់ទ្រាយដូចជាសំពៅមានកម្ពស់ប្រហែល ១០០ម៉ែត្រ និងមានកាំជណ្ដើរ ១០៣កាំ។ គេអាចឡើងភ្នំតាមជណ្ដើរថ្មបត់បែនចុះឡើងឬមួយប្រើផ្លូវរថយន្តឡើងទៅជិតដល់កំពូលភ្នំ ដល់ទីវត្តក៏បាន។ ភ្នំសំពៅមានល្អាងរូងភ្នំទាំងតូចទាំងធំចំនួន១២ រួមមាន ល្អាងផ្កាស្លា, គក់ទ្រូង, ខ្យល់, តែងខ្លួន, ល្ខោន, ជ្រៃ, ពេជ្រ, ខ្វែង, ប្រេង, ក្បាលខ្មោច, គិរីរម្យនិងល្អាងធំ។ រឿងនិទានពីភ្នំនេះ គឺតភ្ជាប់និងភ្នំបាណន់ដែរ គឺពេលនាងសុវណ្ណមសា ជាប្រពន្ធដើមចៅរាជកុល ប្រើក្រពើឈ្មោះ អាធន់ឱ្យទៅតាមកល់សំពៅនោះពួកពលក្រឡេកឃើញក្រពើធំសម្បើម ក៏ភ័យស្រែកឆោឡោពេញទាំងសំពៅ ខ្លះបោះត្រឡាច ល្ពៅ ព្រមទាំងមាន់និងទាទាំងទ្រុងៗ ទៅឱ្យអាធន់ស៊ី។ ក្នុងពេលនោះនាងរំសាយសក់ក៏ប្រើមន្តវិជ្ជាការឱ្យទឹកសមុទ្រខះរឹងអស់។ ក្រពើក៏ជាប់ក្នុងដីនោះរហូតដាច់ខ្យល់ស្លាប់ កើតទៅជាភ្នំក្រពើ បឹងកន្ទុយក្រពើនិងបឹងច្រមុះក្រពើ។ ឯសំពៅនោះ ក៏កើតទៅជាភ្នំសំពៅ ភ្នំក្ដោងសំពៅ ភ្នំទ្រុងមាន់ទ្រុងទា និងភ្នំអណ្ដើកផងដែរ។ ព្រះរាជាប្រើសេនាឱ្យទៅចាប់នាងសុវណ្ណមសា យកមកសម្លាប់ ដោយកាត់ក្បាលកើតជាភ្នំមួយ ហៅថាភ្នំសងក្បាលយារមកជាភ្នំសងក្បាន វាលចិញ្ច្រាំពោះ ជាទីដែលសេនាចិញ្ច្រាំពោះវៀននាង។ ឯយោនីរបស់នាង សេនាបានគ្រវែងចោលកើតទៅជាភ្នំក្រពាយនាង ហៅយារមកជាភ្នំបន្ទាយនាង។",
    "descriptionEn": "West of Battambang city, about 12 kilometers, there are many nearby mountains such as Phnom Sampov, Phnom Trung Moan-Trung Tea and Phnom Romsay Sak. Phnom Sampov is a mountain with a height of 100 meters and a resort town. A natural destination for tourists on weekends and during festivals, especially during the traditional Khmer New Year and Pchum Ben celebrations. The mountain is shaped like a ship, about 100 meters high and there are 103 steps. You can climb the mountain by taking the stone stairs, up and down or use the car route to get closer to the top of the mountain to the pagoda. The history of this mountain is also linked to Phnom Banan when Sovanmasa, the first wife of Chao Reach Kol, used a crocodile. Athena's name goes to the stern of the ship. When the soldiers see a huge crocodile, they are terrified and scream at the whole ship. Let the sea water freeze. The crocodile is stuck in the ground. Until the wind dies in Crocodile Mountain, Crocodile Tail Lake and Crocodile Nose Lake. The ship also became Phnom Sampov, Phnom Kdong, Sampov, Phnom Trong Moan, Trong Tea and Phnom Andek. The king used his army to capture Sovann Masay and kill her by cutting off her head. As for Sena's vagina, she threw it away and gave birth to Phnom Krapeay.",
