    "id": "rac-k15053",
    "nameKh": "ល្អាងភ្នំទាក់ទ្រាំង, ល្អាងស្ពាន",
    "nameEn": "Teaktraing Mountain Cave, Spean Mountain Cave",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "ល្អាងស្ពានជាឈ្មោះដែលអ្នកស្រាវជ្រាវផ្ដល់ឱ្យ ដោយហៅតាមរូបរាងថ្មដែលមានសណ្ឋានដូចជាស្ពាននៅក្នុងល្អាង។ ភ្នំទាក់ទ្រាំងមានល្អាង ដែលកកើតឡើងនៅចុងស័កទី១ សម័យពែមីញៀង ដែលមានអាយុកាលប្រហែល៣០០លានឆ្នាំមុនគ្រឹស្តសករាជ។ នៅទសវត្សទី៦០ (ឆ្នាំ១៩៦៤) លោករ៉ូឡង់-ម៉ូរ៉េ (Roland Mourer) និងប្រពន្ធរបស់គាត់អ្នកស្រីសេស៊ីល (Cécile) បានមកដល់ល្អាងស្ពាននេះហើយគាត់បានធ្វើកំណាយសាកល្បង នៅលើផ្ទៃដីសរុបចំនួន១៥ម៉ែត្រក្រឡា ដែលចែកជាបីរណ្ដៅនៅក្នុងផ្ទៃរូងទាំងមូល។ រូងនេះមានបណ្ដោយ៤២ម៉ែត្រ ទទឹង២០ម៉ែត្រ និងកម្ពស់ពីផ្ទៃដីដល់ពិដាននៃរូងភ្នំប្រហែល២០ម៉ែត្រ។ តាមរយៈការធ្វើកំណាយកាលជំនាន់នោះគាត់បានប្រទះឃើញបំណែកថ្ម និងកម្ទេចកម្ទីកុលាលភាជន៍មួយចំនួន នៅក្នុងស្រទាប់ដែលជ្រៅជាងគេ (ស្រទាប់ទី៩)។ លោករ៉ូឡង់-ម៉ូរ៉េបានបញ្ចប់ការស្រាវជ្រាវលើកដំបូង ដោយឱ្យលទ្ធផលនៅពេលនោះជាកាលបរិច្ឆេទរវាង ៦៩០០០ដល់៦៨០០ឆ្នាំ មុនគ្រឹស្តសករាជ។ វត្ថុសិល្បៈដែលរកឃើញ សុទ្ធតែជាឧបករណ៍សម័យយុគថ្មបំបែកនិងបំណែកវត្ថុប្រើប្រាស់ដែលធ្វើពីដីដុត។ គាត់បានធ្វើការសម្គាល់ថាល្អាងស្ពានជាស្ថានីយ៍បុរេប្រវត្តិសាស្ត្រ ដែលទាក់ទងនឹងការតាំងទីលំនៅក្នុងរូងភ្នំរបស់មនុស្សនាសម័យយុគថ្មបំបែក។ នៅដើមឆ្នាំ២០០៩ គម្រោងសិក្សាស្រាវជ្រាវថ្មីមួយបានធ្វើការសិក្សាបន្ថែមនៅស្ថានីយ៍ដដែលនេះ។",
    "descriptionEn": "Cave Teaktraing is the name given by researchers to the rocky shape of the bridge in the cave. Phnom Teak Traing has a cave that dates back to the late 1st century BC, around 300 million BC. In the 1960s (1964), Roland Mourer and his wife, Cécile, arrived at the cave of the bridge and carried out a test excavation on a total area of ​​15 square meters divided into three pits over the entire surface of the tunnel. The tunnel is 42 meters long, 20 meters wide and about 20 meters high from the floor to the ceiling of the cave. Thanks to the excavations of the time, he found fragments of stone and pottery in the deepest layer (ninth layer). Roland-Mourer completed his first research, dating from 69,000 to 6,800 BC. The artifacts found were all Paleolithic tools, fragments and pieces of pottery. He identified the cave as a prehistoric site associated with the settlement of human caves in the Stone Age. In early 2009, a new research project conducted additional studies at the same station.",
