    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តឈើខ្មៅស្ថិតនៅតំបន់ដែលមានពុទ្ធបរិស័ទរស់នៅលើផ្ទះបណ្ដែតទឹក មានអាយុកាលជាង ១០០ ឆ្នាំហើយ។ ទេសចរតែងចាប់អារម្មណ៍និងសំណង់ព្រះវិហារបុរាណ និងទូកងមួយដែលរក្សាទុកនៅទីនោះ។ ព្រះវិហារ សង់ឡើងពីដើមឈើខ្មៅក្នុងទំហំតូចល្មម ហើយជាពិសេសនៅទីអារាមនេះ ក៏មានទូកង ដែលមានអាយុកាលស្មើនឹងព្រះវិហារមានបារមីខ្លាំង ពេលចេញប្រណាំងមិនដែលចាញ់គេឡើយ។ តាមតំណាលរបស់ចាស់ៗ ពីមុនមានស្តេច១អង្គបានមកបន់ស្រន់នៅលើទីទួលនេះ ទើបជំនឿបន់ស្រន់ចេះតែមានបន្ត។ ប្រហែលនៅឆ្នាំ ១៨០០ មានលោកតាម្នាក់ឈ្មោះ សឿ មានអំណាចនិងឬទ្ធបារមីខ្លាំងមិនខ្លាចពួកបារាំងដែលបានជិះកប៉ាល់មកទីនេះឡើយបានកសាងបានសាឡុម ហើយក្រោយមកគេសាងសង់បានព្រះវិហារលើទីទួលមួយ ឈ្មោះថា «ទួលអណ្ដែត » ដោយដើមឈើខ្មៅដែលសម្បូរនៅទីនេះ។",
    "descriptionEn": "Chheu Khmao Pagoda is located in an area where Buddhists live in floating houses that are over 100 years old. Tourists are always fascinated by the construction of ancient temples and an arch preserved there. The temple is built of black wood in quite a small size, and especially in this temple there is an arch which is the same age as the church, it is very powerful when it comes to running, never losing. According to the legends of the ancients, a king came to pray on this hill, so the faith of prayer continued. Around 1800, a mighty and powerful man named Sister, who was not afraid of the French who sailed here, built a saloon and later built a temple on a hill called “Floating Hill”. Black trees abound here.",
