    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តសោមនស្សគឺជាវត្តមានព្រះវិហារកសាងក្នុងឆ្នាំ១៩៣៧ ប្រកបដោយគំនូរបុរាណ ស្រដៀងនឹងគំនូរនៅថែវព្រះវិហារព្រះកែវមរកតក្នុងព្រះបរមរាជវាំង និងនៅវត្តធោធិរុក្ខារាមនៅកំពង់ត្រឡាចលើដែរ។ ប៉ុន្តែគំនូរនេះមិនស្ដីអំពីរឿងព្រះវេស្សន្តរទេ តែជារឿងកម្រមួយក្នុងបញ្ញាសជាតក គឺរឿង មហាជម្ពូបតី គូរក្នុងទសវត្ស ១៩៤០ ដោយជាងឈ្មោះ ភៀន។ គំនូរនៅលើជញ្ជាំងព្រះវិហារចែកជា៣ផ្នែក គឺខាងលើ, កណ្ដាលនិងខាងក្រោម។ នៅផ្នែកខាងលើគេគូររឿងជម្ពូបតីតាមដំណើររឿងដែលឈុតនីមួយៗនៃសាច់រឿងបន្តគ្នារហូតមិនខ័ណ្ឌចែកជាផ្ទាំងៗទេ។ ផ្នែកកណ្ដាលគេគូរពុទ្ធប្រវត្តិទៅតាមចន្លោះទ្វារនិងបង្អួច ឯចំណែកផ្នែកខាងក្រោម គេគូររឿងព្រេងផ្សេងៗដូចជាធនញ្ជ័យ, ចៅចាក់ស្មុក, មរណមាតាជាដើម។ គំនូរផ្នែកខាងក្រោមនោះរលប់ស្ទើរមើលពុំឃើញ។ រីឯលើពិតានវិញ មានតែពុទ្ធប្រវត្តិ២ផ្ទាំងប៉ុណ្ណោះ គឺព្រះអង្គយាងចេញសាងផ្នួស និងព្រះអង្គកាត់ព្រះកេសា។ រឿងជម្ពូបតីនោះដំណាលពីស្តេច ចក្រពត្តិមួយអង្គមានព្រះនាមថា ជម្ពូបតី មានសុពណ៌បាទ (ស្បែកជើង) មួយគូ ដែលអាចបញ្ជាឱ្យធ្វើអ្វីតាមសេចក្ដីប្រាថ្នា។ ស្ដេចបានប្រើសុពណ៌បាទនោះទៅបង្ក្រាបស្តេចនគរដទៃរហូតបានជានគរចំណុះដល់ទៅ១០១។ ថ្ងៃមួយព្រះអង្គបានសម្លឹងឃើញនគររាជគ្រឹះក៏មានព្រះទ័យចង់បានក៏ប្រើសុពណ៌បាទកើតជានាគទៅគម្រាមស្ដេចព្រះបាទពិម្ពិសារនៃនគររាជគ្រឹះ ឱ្យយកសួយសាអាករមកថ្វាយ។ ព្រះបាទពិម្ពិសារភិតភ័យខ្លាំងណាស់ក៏ទូលដំណឹងនេះថ្វាយទៅព្រះពុទ្ធអង្គដែលគង់នៅឯព្រៃវេឡុវ័នដើម្បីឱ្យព្រះអង្គជួយ។ ព្រះពុទ្ធអង្គដោយមានជំនួយពីព្រះឥន្ទ្រក៏ បំបាត់ភាពអំនួតនិងភាពកាចសាហាវរបស់ជម្ពូបតីហើយក៏សុំសាងផ្នួសក្នុងពេលនោះតែម្ដង។",
    "descriptionEn": "Somnos Pagoda is a temple built in 1937 with ancient paintings similar to the gallery paintings of Preah Vihear Preah Keo Morakot at the Royal Palace and Pothi Rukkaram Pagoda at Kampong Tralach Leu. However, this painting is not about Preah Vesna, but about a rare story in Panhas Cheatak, the story of Maha Chumpoti, painted in the 1940s by an artisan named Phean. The paintings on the walls of the church are divided into three parts: top, middle and bottom. At the top, the story is drawn in chronological order, with each scene of the story continuing in unison. In the central part, they draw the story of the Buddha through the door and the window, while in the lower part, they draw various legends such as Thananyi, Chao Chak Smok, Maranamata, etc. The painting below is almost invisible. As for the ceiling, there are only two Buddhist stories: he went out to build a pagoda and he cut his hair. The story of Chumpoupati, from the time of an emperor named Chumpoupati, has a pair of white shoes (shoes) that can be ordered to do whatever one wishes. The king used this color to defeat the kings of other kingdoms until they became 101 subordinate kingdoms. One day he looked at the royal palace and wanted to use it. King Pimpisar was very scared and announced this news to the Buddha who was at Prey Veluvan for his help. The Buddha, with the help of Indra, eliminated the arrogance and cruelty of the Buddha and asked to build a tower at that time.",
