    "nameKh": "វត្តកែវ, វត្តមុន្នីរតនារាម",
    "nameEn": "Keo Pagoda",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "មានទីតាំងស្ថិតនៅជាប់មាត់ស្ទឹងសង្កែ វត្តកែវត្រូវបានកសាងឡើងនៅឆ្នាំ១៧៧២។ កាលពីដើមវត្តនេះ គឺជាកោះមួយដែលមានទឹកព័ទ្ធជុំវិញ ទើបគេឱ្យឈ្មោះថា វត្តកោះកែវ ឬ វត្តមុន្នីរតនារាម ក្រោយមកពាក្យនេះបានស្ទួននឹងឈ្មោះវត្តដទៃទៀត ក៍បានប្ដូរឈ្មោះមកវត្តកែវរហូតមកដល់សព្វថ្ងៃនេះ។ ខេត្តបាត់ដំបងជាខេត្តមួយដែលសម្បូរទៅដោយ ប្រាសាទបុរាណនិងសំណង់អគារដែលមានវ័យចំណាស់ជាច្រើន ដូចជា វត្តកែវ នេះជាដើម។ នៅទីនោះមាន ព្រះវិហារបុរាណមួយធ្វើពីឥដ្ឋនិងឈើប្រក់ក្បឿង មានហោជាងធ្វើពីឈើប្រកបដោយក្បាច់ផ្កាភ្ញីដ៏ល្អឯក លាបពណ៌មាសគួរឱ្យចង់គយគន់។ ពិដាននៃព្រះវិហារនេះក៏មានបិទក្បាច់ដ៏ឆើតឆាយ និងស្រស់ស្អាតជាទីបំផុត។ ទេសចរជាតិនិងអន្តរជាតិដែលបានទៅទស្សនានៅវត្តនេះហើយ តែងពោលសរសើរពីស្នាដៃដ៏អស្ចារ្យ ស្រមៃដល់ភាពរីចម្រើនរបស់ព្រះពុទ្ធសាសនាពីអតីតកាល។",
    "descriptionEn": "Located on the banks of the Sangker River, Keo Pagoda was built in 1772. In the past, this pagoda was an island surrounded by water, so it was called Koh Keo Pagoda or Mony Ratanaream Pagoda. Later, the word was duplicated by other pagodas and changed its name to Keo Pagoda until today. Battambang is a province rich in ancient temples and many ancient buildings like the Keo Pagoda. There is an ancient temple made of bricks and tiles, with a wooden chandelier decorated with beautiful flowers and gold. The ceiling of this church is also decorated with the most elegant and beautiful. Domestic and international tourists who visit this pagoda often praise the great works imagining the progress of Buddhism in the past.",
    "photoUrl": "https://raw.githubusercontent.com/igpubinfo-max/Khmer-Food-Tourism/8d322f9/public/destinations/rac-k15057.jpg",
    "provinceKh": "ខេត្តបាត់ដំបង",
    "provinceEn": "Battambang",
