    "id": "rac-k15058",
    "nameKh": "សារមន្ទីរសន្តិភាពកម្ពុជា",
    "nameEn": "Cambodian Peace Museum",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "សារមន្ទីរដំបូងគេដែលនិយាយអំពីសន្តិភាព និងការផ្សះផ្សារបានបើកទ្វារជាផ្លូវការដល់សាធារណជន ដែលចាប់អារម្មណ៍ក្នុងការសិក្សាលើភាពវិជ្ជមាននៃប្រវត្តិសាស្ត្រសង្គ្រាមដែលកម្ពុជាបានឆ្លងកាត់។ សារមន្ទីររូបភាពថ្មីស្រឡាងមួយ នេះបានបើកទ្វារដំណើរការនៅឆ្នាំ ២០១៨ សម្រាប់ឱ្យប្រជាជនកម្ពុជាទាំងឡាយ ដែលមានចំណាប់អារម្មណ៍ចង់សិក្សាស្វែងយល់អំពីបទពិសោធន៍ នៃសង្គ្រាម ជម្លោះស៊ីវិល និងការផ្សះផ្សារជាតិនៅកម្ពុជា។ សារមន្ទីរសន្តិភាពកម្ពុជា មានវិចិត្រសាលរូបភាពដែលបែងចែកជាបីអគារ។ អគារទី១ មានបង្ហាញនូវការបញ្ចប់សង្គ្រាមស៊ីវិលនៅកម្ពុជា និងដំណើរការចរចាស្វែងរកសន្តិភាពនៅកំឡុងដើមទសវត្សរ៍ឆ្នាំ១៩៩០។ អគារទី២ គឺផ្ដោតទៅលើរយៈពេលនៃការងើបឡើងវិញ និងការស្ថាបនាឡើងវិញក៏ដូចជាការខិតខំប្រឹងប្រែងដោះមីនជាដើម។ ចំណែកអគារចុងក្រោយ បង្ហាញពីរូបគំនូររបស់មនុស្សដែលបានរស់នៅអំឡុងពេលសង្គ្រាម អ្នកដែលបានរស់រានមានជីវិត និងអ្នកដែលរស់នៅដើម្បីជួយជំរុញការផ្សះផ្សារឡើងវិញ។",
    "descriptionEn": "The first museum to talk about peace and reconciliation has officially opened its doors to the public interested in studying the positive aspects of Cambodia's war history. This brand new museum opened in 2018 for Cambodians to learn more about Cambodia's experiences of war, civil conflict and national reconciliation. The Cambodian Peace Museum has a picture gallery divided into three buildings. The first building marks the end of Cambodia's civil war and peace process in the early 1990s. The second building focuses on the period of recovery and reconstruction, as well as mine clearance efforts. The final building features paintings of people who lived through the war, survivors and those who helped promote reconciliation.",
