    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "ផ្ទះបុរាណខ្មែរធ្វើពីឈើដែលមានអាយុកាលជិត ១០០ឆ្នាំ នៅក្រុងបាត់ដំបងជាទីកន្លែងទាក់ទាញភ្ញៀវទេសចរជាតិនិងអន្តរជាតិទៅកម្សាន្តយ៉ាងកុះករ។ ផ្ទះបុរាណខ្មែរទាំងនោះភាគច្រើនជាប្រភេទផ្ទះប៉ិតធ្វើអំពីឈើ និងមានដំបូលប្រក់ក្បឿង។ ផ្ទះយាយប៊ុនរឿងមានទទឹងប្រមាណ ១០ម៉ែត្រកន្លះ និងបណ្ដោយ ២៩ម៉ែត្រ មានអាយុកាល១០ទសវត្សរ៍នេះ នៅរឹងមាំនិងមានជណ្ដើរចំនួន២។ នៅពេលព្រឹកពុំសូវមានទេសចរទេ ប៉ុន្តែភាគច្រើនភ្ញៀវនិយមទៅទស្សនានៅពេលរសៀល។ យាយប៊ុន រឿង ជាម្ចាស់ផ្ទះជំនាន់ទី៣ ដែលផ្ទះនេះជាកេរពីជីតារបស់គាត់ឈ្មោះ ឧកញ៉ា នូ ពិនិត្តភិង សង់ឡើងនៅឆ្នាំ១៩២០។ លោកតាគាត់មានកូនប្រុសម្នាក់ និងស្រីចំនួន ៦នាក់។ ផ្ទះបុរាណមួយនេះមានសភាពរឹងមាំ និងស្រស់ស្អាត មានទីធ្លាធំទូលាយ អមទៅដោយដើមឈើតូចធំព័ទ្ធជុំវិញផ្ទះ ពោលគឺមានគុណភាពមិនចាញ់ផ្ទះសម័យថ្មីឡើយ។",
    "descriptionEn": "The traditional Khmer wooden houses which are nearly 100 years old in Battambang city are a place that attracts many domestic and international tourists to visit. Most traditional Khmer houses are wooden houses with tiled roofs. Yeay Bun Roeung's house is about 10.5 meters wide and 29 meters long, it is ten years old, it is solid and has two stairs. In the morning, there are not many tourists, but most visitors visit in the afternoon. Yeay Bun Roeung owns the third-generation house, inherited from his grandfather, Duke Nou Pinit Ping, built in 1920. His grandfather had one son and six daughters. This traditional house is solid and beautiful, with a large yard surrounded by small and large trees around the house, the quality is not inferior to modern houses.",
