    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "ក្នុងសម័យកម្ពុជាប្រជាធិបតេយ្យ ទីនេះក្លាយជាជា​កន្លែង​ឃុំឃាំង​ ធ្វើទារុណកម្ម​ និង ​ជា​កន្លែង​សម្លាប់​មនុស្ស​យ៉ាង​សាហាវ​ព្រៃផ្សៃ​បំផុត។ បច្ចុប្បន្ននេះវត្តសំរោងក្នុង បានក្លាយទៅជាតំបន់ទេសចរណ៍ប្រវត្តិសាស្រ្តផង និងបូជនីយដ្ឋានប្រល័យពូជសាសន៍ដែលគួរឱ្យចាប់អារម្មណ៍ផងដែរ។ នៅឆ្នាំ១៩៨០ អដ្ឋិធាតុជាច្រើនត្រូវបានគាស់ឡើង មានឆ្អឹងលលាដ៏ក្បាលនិងឆ្អឹងដងខ្លួនដែលត្រូវបានបោះគរនៅលើមាត់រណ្ដៅ។ រណ្ដៅជាច្រើនដែលស្ថិតនៅជុំវិញមន្ទីរបូជនីយដ្ឋាន ត្រូវគាស់ទាំងអស់ ហើយស្លាកស្នាមនៅមិនទាន់រលប់នៅឡើយ។ បូជនីយដ្ឋានមួយបានត្រូវសាងសង់ដើម្បីដាក់អដ្ឋិធាតុទាំងនោះ ដែលមានលលាដ៍ក្បាល​និងអដ្ឋិធាតុ​ប្រមាណ ​១០០០៨​នាក់ ត្រូវ​បានគេ​ជីកកកាយ​ពីស្រះ​និងរណ្ដៅ​ចំនួន១០០​ នៅ​ជុំវិញ​បរិវេណវត្ត​សំរោងក្នុង​សព្វថ្ងៃ​។",
    "descriptionEn": "In the era of Democratic Kampuchea, this place has become a place of detention, torture and the most brutal place to kill people. Today, Samrong Knong Pagoda has become a historical tourist site and also interesting is the Genocide Monument. In 1980, many remains were unearthed, with skulls and body bones piled up at the mouth of the pit. And the mark has not yet disappeared. A monument was erected to house the remains, with around 1,008 skulls and remains unearthed from 100 ponds and pits. Around Samrong Pagoda today.",
