    "descriptionKh": "ពីសម័យបុរាណប្រាសាទនេះនៅមានទ្រង់ទ្រាយ ល្អមានទំហំស្មើនឹងព្រះវិហារសព្វថ្ងៃ ដែលកសាងត្រួតពីលើទីតាំងចាស់។ ក្នុងសម័យខ្មែរក្រហម ប្រាសាទដូនអន ត្រូវបានបំផ្លាញទាំងស្រុង ដើម្បីយកថ្មប្រាសាទទៅកសាងស្ពានឬ ទំនប់ទឹកដែលពិតជាគួរឱ្យស្តាយណាស់។ លុះក្រោយមក ពេលប្រទេសមានសន្តិភាពវិញទីតាំងប្រាសាទនេះត្រូវបានប្រជាពលរដ្ឋរៀបចំធ្វើជាវត្ត ហើយប្រមូលថ្មប្រាសាទដែលនៅសេសសល់រក្សាទុករហូតដល់បច្ចុប្បន្ននេះ។ ទម្រង់ដើមនៃប្រាសាទនេះ គឺមានកំពែងពីរជាន់ ប្រកបដោយគូទឹកព័ទ្ធជុំវិញ មានប្រាង្គកណ្ដាលមួយ និងនៅខាងត្បូងមួយ។ ជនរងគ្រោះនៃរបបខ្មែរក្រហមម្នាក់បានឱ្យដឹងថា ប្រាសាទដូនអនដែលធ្វើពីថ្មភក់ទំហំប្រហែល ១២ ម៉ែត្រ បួនជ្រុង មានផ្ដែរ ហោជាង សសរពេជ្រ ត្រូវប្រធានកង ប្រធានសហករណ៍បញ្ជាឱ្យប្រជាជនក្នុងភូមិធ្វើការរុះរើសំណង់ប្រាសាទទាំងអស់យកទៅ ធ្វើទ្វារប្រឡាយ ១៧ មេសា។ ក្នុងការរើរុះប្រាសាទគឺប្រធានសហករណ៍តម្រូវឱ្យកាប់គាស់ និងវាយកម្ទេចថ្មជាបំណែកតូចៗបន្តទៀត ដើម្បីយកទៅចាក់ធ្វើទ្វារទឹក រយៈពេលជាងមួយខែទើបរួចរាល់។ នេះគឺជាការកម្ទេចដើម្បីបំបាត់ភ័ស្ដុតាងហើយក៏ជាការបំផ្លាញវត្តអារាមផងដែរ ដោយពួកខ្មែរក្រហមបានយកសាស្ត្រាស្លឹករឹតទៅដេរធ្វើមួកពាក់ទៀតផង។",
    "descriptionEn": "Since ancient times, this temple is still in good condition, the size of today's temple, which was built on the ancient site. During the Khmer Rouge era, Daun An temple was completely destroyed to take the stone to build a bridge or a dam, which is really sad. Later, when the country was peaceful, the location of this temple was organized by the people as a pagoda and the remaining stone stones were collected and preserved until today. The original form of this temple is a two-storey wall with a moat. Surrounded by a central tower and a south tower. One of the victims of the Khmer Rouge regime said that the sandstone Daun An Temple, about 12 square meters, had more than a diamond pillar. In the village, all temple structures were dismantled to make way for the canal gate. It's done. This was demolished to destroy the evidence and also to destroy the pagoda, as the Khmer Rouge used manuscripts to make hats.",
