    "descriptionEn": "There is a natural landscape with waterfalls and forests. Visitors can bathe, swim in the river or relax in the tranquility of the eight-story waterfall, about 2 km away. The waterfall flows from the top of the mountain Oral, the rainy season, through the rocks hundreds of meters cold like the water of Amret. This natural waterfall is often compared to Busra waterfall in Mondulkiri province, saying that in Cambodia, apart from Busra waterfall, there is only this natural waterfall, which is shaped like a waterfall of the source under the mountain. Each will have a similar beauty of running water. It is true that Busra Waterfall has been famous since ancient times, but Chrak Laeang Natural Waterfall was only included in the provincial tourist list in 2003, and there are tourists visiting the same place as the Busra waterfall.",
