    "descriptionKh": "ទឹកធ្លាក់ឆាយសន្ទរ មានសក្ដានុពលទេសចរណ៍ធំធេងក្នុងស្រុកភ្នំក្រវាញ ដោយមានទឹកហូរពីលើភ្នំ កាត់ទៅរកស្ទឹងពោធិ៍សាត់។ ទិដ្ឋភាពដ៏គួរឱ្យទាក់ទាញមួយខុសពីទឹកធ្លាក់ដទៃនៅតំបន់នេះ ដោយជ្រលងទឹកមានជម្រៅរាក់ៗ ហូរកាត់តាមគល់រុក្ខជាតិមិនមានល្បាក់ខ្ពស់ទេ។ តំបន់រមណីយដ្ឋាននេះ ទើបតែរកឃើញហើយអាចទៅកម្សាន្តបាន ដោយដំណើរទៅកាន់ទីនោះ ទេសចរនឹងឆ្លងកាត់ភូមិក្សេត្របុរី ដែលជាអតីតតំបន់អភិវឌ្ឍន៍របស់សម្ដេចព្រះសីហនុ។ ពីដើមតំបន់នេះមានព្រៃជុំជិត មានផ្លូវចេញតែមួយគត់ ទើបសម្ដេចព្រះសីហនុយកអ្នកទោសមករស់នៅ ហើយបានទាំងកសាងព្រះរាជដំណាក់មួយក្នុងភូមិក្សេត្របុរីនោះទៀតផង (សព្វថ្ងៃនៅសល់ក្លោងទ្វារ)។ ទីតាំងនេះក៏ស្ថិតនៅក្នុងតំបន់យកថ្មកែវដែលជាថ្មដ៏កម្រមានតែនៅទឹកដីខេត្តនេះផងដែរ។",
    "descriptionEn": "Chhay Son Waterfall has great tourism potential in the Cardamom Mountains, with water flowing from the mountain to the Pursat River. An attractive view differs from other waterfalls in the area, with shallow valleys running through the base of the plant, not high cascades. This resort area has just been discovered and can be visited by tourists passing through the village of Kset Borey, a former development area of ​​Prince Sihanouk. Originally the area was surrounded by forest and there was only one exit, so Prince Sihanouk kept prisoners alive and even built a royal house in the village of Kset Borey (now the gate remains ). This location is also in the quarry area, which is a rare rock only in this province.",
