    "categorySlug": "nature",
    "categoryKh": "ធម្មជាតិ & ទឹកធ្លាក់",
    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "ល្បាក់ទឹកហូរធ្លាក់លើថ្មដែលផុសចេញពីផ្ទៃបាតស្ទឹងពោធិ៍សាត់នារដូវវស្សា។ ប្រវត្តិរបស់ល្បាក់កំរោញនេះគឺ នៅទីនេះកាលពីដើមឡើយមានផ្ទាំងថ្មមួយធំប្រៀបបានដូចជាជញ្ជាំង ដែលរាំងកាត់ស្ទឹងបង្កើតបានទៅជាល្បាក់ទឹកហូរធ្លាក់យ៉ាងខ្លាំងបណ្ដាលឱ្យជួបការលំបាកក្នុងការធ្វើដំណើរឆ្លងកាត់សូម្បីតែហ្វូងមច្ឆជាតិគ្រប់ប្រភេទក៏កម្រនឹងហែលឆ្លងផុតពីល្បាក់ទឹកនេះណាស់។ អ្នកស្រុកភូមិទីនេះនាំគ្នាហៅថា «ល្បាក់កម្រទៅរួច»គឺគ្រប់អ្នកដំណើរកម្រនឹងឆ្លងផុតល្បាក់ទឹកនេះណាស់ ទើបយារក្លាយមកជា ល្បាក់កំរោញ។ ដោយសារហេតុផលនេះហើយគេក៏យកកន្លែងនេះធ្វើជាកន្លែងចំណតរង់ចាំអ្នកឡើងពីក្រោម និងអ្នកចុះពីលើដើម្បីលក់អីវ៉ាន់ឬដោះដូរអីវ៉ាន់គ្នាទៅវិញទៅមក។ កាលដើមល្បាក់កំរោញនេះសំបូរមច្ឆាណាស់ព្រោះវាមិនអាចហែលឆ្លងកាត់រួច ទើបអ្នកស្រុកនៅម្ដុំនោះតែងតែទៅចាប់យកមកធ្វើជាប្រហុក ផ្អក ងៀត និងឆ្អើរសម្រាប់លក់ដូរបានទៀតផង។ ឈ្មួញរកស៊ីកាប់ព្រៃឈើបានមកធ្វើសកម្មភាពនៅទីនោះ រួចគេបានបង្អូសឈើជាក្បួនបានជួបការលំបាកនឹងផ្ទាំងថ្មល្បាក់ទឹកនោះ ទើបពួកគេបានដាក់មីនបំផ្លាញចោលផ្ទាំងថ្មដ៏ធំនោះ ដែលមកដល់ពេលនេះនៅសល់តែបំណែកបាក់បែកតែប៉ុណ្ណោះ។ ទោះជាយ៉ាងណាក៏បច្ចុប្បន្នល្បាក់កំរោញនៅតែមានទេសភាពដ៏ស្រស់ស្អាត គង្គាថ្លាឆ្លុះដល់បាតស្ទឹង ទឹកហូរធ្លាក់ជាដំណាក់ៗខួបប្រាំងវស្សាសម្រាប់ភ្ញៀវទេសចរងូតកម្សាន្តដដែល។",
    "descriptionEn": "The waterfalls tumble over the rocks that emerge from the bottom of the Pursat River during the rainy season. The story of this waterfall is that here in the past, there was a big rock like wall that crossed the river, forming a huge waterfall, making it difficult for even all kinds of fish to pass. Rarely swims past this waterfall. The villagers call this \"rare waterfall\", it is very rare that all travelers cross this waterfall to become a waterfall. For this reason, it is also used as a Kampong, waiting for you to get up to sell or trade items among yourselves. At first, this waterfall was very fishy because it could not swim across, so locals always went to fish it like dry Prahok and roast it to sell. Deforestation traders came to operate there, and as a result, they were forced to remove the logs, encountering difficulties with the rock, so they laid mines to destroy the huge rock, which is now only a fragment, only broken. However, at present, Lbak Kamronh still has a beautiful view of the Ganges, reflecting the bottom of the river, flowing in stages, the rainy season for tourists to bathe.",
