    "descriptionKh": "ទឹកធ្លាក់ថ្មដាតូចជារមណីយដ្ឋានធម្មជាតិមួយកន្លែងដែលកំពុងល្បីល្បាញ បន្ទាប់ពីមានការកសាងផ្លូវជាតិលេខ៥៥ រួចរាល់។ ឥឡូវនេះអ្នកស្រុកខេត្តពោធិ៍សាត់និងទេសចរជាច្រើនបានទៅលេងកម្សាន្តជារឿយៗ ព្រោះទឹកធ្លាក់នេះ ស្ថិតនៅប្របផ្លូវជាតិងាយស្រួលទៅដល់ណាស់។ អ្នកស្រុកទីនោះនិយាយថា ពីមុនមិនមានអ្នកណាទៅលេងឡើយក្រៅពីអ្នកភូមិក្បែរនេះ ព្រោះថាផ្លូវពិបាកត្រូវដើរច្រើនគីឡូម៉ែត្រ។ ទឹកធ្លាក់ថ្មដាតូចឬអ្នកខ្លះនិយមហៅទឹកធ្លាក់ភ្នំ១៥០០ មាន ២ដំណាក់ ដែលដំណាក់ខាងលើ ជាទីដែលទេសចរដើរដល់មុន ជាទីសម្រាប់ងូតទឹកលេងកម្សាន្ត ដោយសារដំណាក់នេះ មានទឹកធ្លាក់ហូរលើជម្រាលជាថ្នាក់ៗ ដូចកាំជណ្ដើរ។ ចំណែកដំណាក់ខាងក្រោម គឺជាល្បាក់ទឹកធ្លាក់ កម្ពស់ជិត១០ម៉ែត្រ ដែលទេសចរក៏អាចមុជទឹកលេងនៅទីនោះបានដែរ។ ទឹកធ្លាក់ថ្មដាតូចមានទឹកហូរខួបប្រាំង ខួបវស្សា គ្រាន់តែនៅរដូវប្រាំង មានទឹកហូរតិចប៉ុណ្ណោះ។",
    "descriptionEn": "Small Rock Waterfall is a natural resort which became famous after the construction of National Road 55. Now many locals and tourists from Pursat province visit this waterfall because it is very close to the national road. Locals say that before, no one visited except the neighboring villagers as the road was difficult to walk for several kilometres. The small rock waterfall, or as some people call it, 1500 mountain waterfalls, two-stage, the upper stage is where tourists step first, as a place to take a bath, because this stage has a waterfall flowing down the slope like a staircase. The lower level is a waterfall almost 10 meters high where tourists can also dive into it. Small rock waterfalls have water flow, the dry season, the rainy season, only in the dry season there is less water flow.",
