    "descriptionKh": "ទឹកធ្លាក់ថ្មដាធំ ជារមណីយដ្ឋានធម្មជាតិដ៏ស្រស់បំព្រងមួ នៅជាប់ព្រំដែនកម្ពុជាថៃ ដែលអាចធ្វើដំណើរបានដោយស្រួលបន្ទាប់ពីមានផ្លូវជាតិលេខ៥៥ តាមផ្លូវចង្កេះភ្នំក្ងិចក្ងក់ អមដោយទេសភាពព្រៃភ្នំគួរឱ្យទាក់ចិត្ត។ ទេសចរតែងតែមិនភ្លេចផ្ដិតរូបភាពស្រស់បំព្រងនៃទស្សនីយភាពធម្មជាតិនេះ អមដោយសំឡេងទឹកធ្លាក់រណ្ដំឮឈូឆរឥតឈប់។ ទឹកធ្លាក់ថ្មដាធំមានប្រភពជាទឹកធម្មជាតិធ្លាក់ពីប្រជុំភ្នំក្រវាញ ហូរខួបប្រាំងវស្សាថ្លាដូចកញ្ចក់ធ្លាក់តាមដំណាក់នីមួយៗ គួរឱ្យចង់ងូតលេងកម្សាន្ត។ ទឹកធ្លាក់នេះកើតចេញពីការរញ្ជួយដីបាតស្ទឹងជ្រែកកាត់ជ្រលងភ្នំ ធ្វើឱ្យលេចចេញនូវផ្ទាំងថ្មជ្រុងៗយ៉ាងធំសម្បើមជាច្រើនផ្ទាំង ប្រៀបដូចគេដាប់បម្រុងជញ្ជូនយកទៅធ្វើមហាវិមានឬមហាប្រាសាទយ៉ាងអ៊ីចឹង គួបផ្សំនឹងខ្សែទឹកសថ្លាញ៉ាំងទិដ្ឋភាពកណ្ដាលព្រៃនៃតំបន់ថ្មដា រឹតតែមានបរិយាកាសស្រស់ស្រាយ។",
    "descriptionEn": "Thmar Da Thom Waterfall is a beautiful natural resort on the Cambodian-Thai border which is easily accessible after National Road 55 along the ridge accompanied by attractive mountain scenery. Tourists never forget to take beautiful photos of this natural landscape accompanied by the sound of waterfalls and rumblings. Thmor Da Thom Waterfall has a natural spring of water falling from the Cardamom Mountains, which flows in the rainy season, clear as glass falling at every step, it is desirable to bathe and play. This waterfall is caused by an earthquake at the bottom of the river, interspersed with valleys, causing huge boulders to appear at the corners. The view of the middle of the forest from the rocky area is even more refreshing.",
