    "categorySlug": "nature",
    "categoryKh": "ធម្មជាតិ & ទឹកធ្លាក់",
    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "ស្ទឹងមេទឹកជាស្ទឹងមានទឹកគ្រប់រដូវកាល ដែលអ្នកអានសៀវភៅស្ដីពីប្រវត្តិតស៊ូរត់ចេញពីរបបប៉ុលពត «ជីវិតកូនថ្លៃកូនត្រូវតែរស់» របស់លោកពិនយ៉ាថៃបានរៀបរាប់យ៉ាងកម្សត់នោះ។ សម្រស់ធម្មជាតិនៃស្ទឹងមេទឹកនៅឃុំថ្មដា គឺមានទឹកថ្លាត្រជាក់ហូរធ្លាក់តាមចន្លោះផ្ទាំងថ្មដាធំៗ បែកផ្កាត្រែង សម្រាប់ងូតលេង មានព្រៃឈើក្រាលគ្របក្រាស់ឃ្មឹក។ ស្ទឹងមេទឹក ដែលជាទីស្នាក់អាស្រ័យផងដែររបស់សត្វក្រពើភ្នំ ដែលស្ទើរតែផុតពូជទៅហើយនោះ។ ទេសភាពមួយបែបផ្សេងទៀតនៅតាមមាត់ស្ទឹងនិងតំបន់ក្បែរៗបានបង្កភាពរីករាយដល់ទេចរ ជាពិសេសនៅទីនេះមានរីស៊តឯកជនជាច្រើន ដែលមានកន្លែងសម្រាក បោះតង់ មានទឹកអូរហូររ៉ឹមៗ មានសេវាកម្មម្ហូបអាហារ និងទីទស្សនាទេសភាពជាច្រើនទៀត។ ការជិះកាណូត ឬទូកទស្សនាកម្សាន្តនៅតាមដងស្ទឹងមេទឹក ក៏ជាចំណុចគួរឱ្យចាប់អារម្មណ៍ផងដែរ ពីព្រោះសម្រស់ធនធានធម្មជាតិនៅអមសងខាងស្ទឹង សុទ្ធតែអាចផ្ដល់នូវអារម្មណ៍ស្រស់ស្រាយដល់ទេសចរគ្រប់ៗគ្នា។",
    "descriptionEn": "Stung Meteuk is a river of water in all seasons, which readers of the book on the history of the struggle to escape the Pol Pot regime, \"The life of a son-in-law, a child must live\", sadly describes. The natural beauty of the Meteuk River in Thmor Da Commune is the clear and cool water flowing between the large cliffs, the cacti for bathing and the thick forest. Stung Meteuk, which is also home to the endangered mountain crocodile. Another kind of landscape along the river and surroundings is pleasant for tourists, especially here there are many private resorts with camping tents, flowing streams, food service and many other scenic spots . . Taking a boat or boat trip along the Mekong is also an interesting point because the beauty of natural resources on both sides of the river can bring a refreshing feeling to every tourist.",
