    "descriptionKh": "ឈ្មោះភ្នំ១០០៥ឬភ្នំ១៥០០ទាំងពីរនេះ តាមរយៈសូរអានបែបខ្មែរដែលតែងកាត់ពាក្យខ្លះចោល គឺដូចគ្នា។ តើមួយណាជាឈ្មោះផ្លូវការ? ការបំភ្លឺរបស់ក្រសួងបរិស្ថានគឺ ឈ្មោះភ្នំ១០០៥ គឺហៅតាមផែនទីភូមិសាស្រ្ត របស់យោធាក្នុងសម័យសង្គ្រាមស៊ីវិល។ ចំណែកឈ្មោះភ្នំ១៥០០ គឺហៅតាមរយៈកម្ពស់ភ្នំ ធៀបនឹងនីវ៉ូទឹកសមុទ្រ តែកម្ពស់ពិតអាចដល់ទៅ១៦០០ម៉ែត្រ។ ដូចនេះ «ភ្នំ១៥០០» ជាឈ្មោះផ្លូវការ តាមរយៈបង្គោលគីឡូម៉ែត្រនៅតាមផ្លួវជាតិលេខ៥៥ ដែលមានប្រវែងសរុបជាង ១៨២ គីឡូម៉ែត្រ។ សម្រាប់ទេសចរគ្រប់រូប គេអាចទទួលបាននូវក្ដីរីករាយក្នុងដំណើរដ៏វែងឆ្ងាយពីសម្រស់ព្រៃព្រឹក្សា ភ្នំនានាដែលស្ថិតក្នុងជួរភ្នំក្រវាញ ដែលជាតំបន់មិនទាន់រុករាន។ ភ្ញៀវទេសចរអាចជ្រើសស្នាក់នៅក្នុងទីរួមស្រុកវាលវែង ដែលមានផ្សារនិងផ្ទះសំណាក់ ឬបន្តដំណើរទៅឃុំក្រពើពីរនៅផ្នែកខាងជើង ដែលសម្បូរដោយទេសភាពភ្នំនៃតំបន់សំឡូតដូចជាភ្នំទំព័រជាដើម។ ជម្រើសពីរផ្សេងទៀត គឺតំបន់អូរសោមដែលមានទេសភាពព្រៃភ្នំនៃតំបន់អូរសោមនិងភ្នំសំកុះជាដើម។ ជម្រើសចុងក្រោយដែលកំពុងពេញនិយម គឺបន្តដំណើរត្រង់ទៅកាន់ច្រកព្រំដែនថ្មដា។",
    "descriptionEn": "The names Phnom 1005 or Phnom 1500, both pronounced in the Khmer style, are often the same. What is the official name? According to the Ministry of Environment, the name Phnom 1005 is based on the military map of the army during the civil war. The name Montagnes 1500 is called by the height of the mountain above sea level, but the actual height can reach 1600 meters. Thus, \"Montagnes 1500\" is the official name of the milestone along National Road 55, with a total length of more than 182 kilometers. For every tourist, they can enjoy a long journey of the beauty of mountains and forests in the Cardamom Mountains, an undeveloped area. Tourists can choose to stay in the town of Veal Veng, which has a market and guesthouses, or continue to Crocodile Township in the north, rich in mountain views of the Samlot region, such as Phnom Page . The other two options are the Osom region, which features a mountainous landscape of the Osom and Phnom Samkos regions. The last popular option is to continue straight to the rocky border.",
