    "id": "rac-k16020",
    "nameKh": "ទេសភាពអូរសោម",
    "nameEn": "O Som Landscape",
    "categorySlug": "nature",
    "categoryKh": "ធម្មជាតិ & ទឹកធ្លាក់",
    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "អូរសោម ជាសហគមន៍ជនបទតូចមួយស្ថិតនៅចំកណ្ដាលជួរភ្នំក្រវាញរវាងតំបន់អភិរក្សក្រពើភ្នំ និងភ្នំសំកុះ ភាគនិរតីប្រទេសកម្ពុជាកំពុងប្រែក្លាយជាគោលដៅអេកូទេសចរណ៍និងអ្នកនិយមសម្រស់ធម្មជាតិមកពីគ្រប់ច្រកល្ហក។ ភូមិឋានដ៏ស្ងប់ស្ងាត់ចំនួន ៤ ដែលមានប្រជាជនសរុបប្រមាណ ៤០០ គ្រួសារភាគច្រើនជាជនជាតិដើមភាគតិច ជង គឺជាមជ្ឈមណ្ឌលទេសចរណ៍ដែលផ្ដល់បទពិសោធជីវិតបែបជនបទសម្រាប់ភ្ញៀវបរទេសមុនពេលពួកគេធ្វើដំណើរទៅកាន់ទីក្រុងវប្បធម៌ និងប្រវត្តិសាស្ត្រ។ ទេសចរអាចដើរលេងតាមភូមិ ឡើងភ្នំសំកុះ ទស្សនាអាងក្រពើ ទឹកធ្លាក់ឆាយរកា និងឆាយប្រុយជាដើម។ មជ្ឈមណ្ឌលសហគមន៍ក្រវាញអូរសោម (Osoam CCC) ត្រូវបានបង្កើតឡើងក្នុងបំណងបង្កើនគុណភាពនៃការរស់នៅតាមរយៈការអប់រំ បណ្ដុះបណ្ដាលវិជ្ជាជីវៈ អេកូទេសចរណ៍ និងកម្មវិធីកសិកម្មជាដើម។",
    "descriptionEn": "O'Som, a small rural community in the middle of the Cardamom Mountains between the Crocodile Mountains Conservation Area and Phnom Samkos in southwestern Cambodia, is becoming an ecotourism and natural beauty destination for all walks of life. Four quiet villages with a total population of around 400 families, mostly indigenous, are tourist centers that provide an experience of rural life to foreign visitors before they travel to the cultural and historical city. Tourists can visit villages, climb mountains, visit Crocodile Pool, Chhay Roka Waterfall and Chhay Pruy. The Osoam CCC Community Center was established with the aim of improving the quality of life through vocational education, ecotourism and agricultural programs.",
    "photoUrl": "https://raw.githubusercontent.com/igpubinfo-max/Khmer-Food-Tourism/8d322f9/public/destinations/rac-k16020.jpg",
