    "id": "rac-k16021",
    "nameKh": "កោះសំពៅមាស",
    "nameEn": "Sampov Meas Island",
    "categorySlug": "nature",
    "categoryKh": "ធម្មជាតិ & ទឹកធ្លាក់",
    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "កោះខ្សាច់មួយនៅកណ្ដាលស្ទឹងពោធិ៍សាត់ ក្នុងទីរួមខេត្តបានរចនាកែច្នៃជារាងសំពៅ មានសួនច្បារជាទីលំហែកម្សាន្ត។ គេអាចមើលឃើញកោះនេះគ្រាន់តែចូលដល់ក្រុងពោធិ៍សាត់ភ្លាម។ ប្រវត្តិកោះសំពៅមាសនេះមិនមានឯកសារណាច្បាស់លាស់ទេ គ្រាន់តែឮគេតំណាលតៗគ្នាថា មានសំពៅមួយដែលមកពីស្រុកចិនបានចូលមកដឹកទំនិញនៅម្ដុំផ្សារក្រោមខេត្ត ពោធិ៍សាត់នេះ តែបានលិចហើយដោយមិនអាចស្រង់វិញបាន។ ទឹកបានហូរនាំល្បាប់ដីខ្សាច់មកព័ទ្ធទីនោះហើយក៏បានក្លាយទៅជាកោះ។ រឿងមួយទៀត តំណាលថា កោះសំពៅមាសនោះ គឺជាកន្លែងដែលនាងពេញ ជាបាវបម្រើលោកជំទាវ ខាន់ ខៀវ ប្រពន្ធលោកឧកញ៉ាឃ្លាំង មឿង បានទៅលោតទឹកសម្លាប់ខ្លួនតាមចៅហ្វាយ ហើយនិងកូនពីរនាក់ទៀត។ ប៉ុន្តែយោងតាមសៀវភៅ “ព្រះស្តេចកន” របស់បណ្ឌិត រស់ ចន្ត្រាបុត្រ អ្នកម្នាង ខៀវ ជាស្នំឯករបស់ព្រះអង្គចន្ទរាជា ហើយនាង ពេញ ជាអ្នកបម្រើ របស់ អ្នកម្នាងទៅវិញ។ នាង ពេញ មុនពេលលោតទឹកនោះបានបួងសួងថា “ខ្ញុំសូមឱ្យបានទៅជួបនឹងចៅហ្វាយខ្ញុំ ហើយឱ្យកើតជាបិសាចនៅស្រុកនេះ”។ នាងពេញបានលោតសម្លាប់ខ្លួនក្នុងស្ទឹងពោធិ៍សាត់ជិតផ្សារក្រោមនោះ ហើយបានកើតជាបិសាចថែរក្សាដំបូកលើកោះនេះ។ កោះសំពៅមាសតែងមានទេសចរចូលទស្សនាពេញមួយសប្ដាហ៍ព្រោះស្ថិតនៅក្នុងក្រុង។",
    "descriptionEn": "A sand island in the middle of the Pursat River in the provincial town is designed in the shape of a ship with a garden as a recreation area. The island can be seen simply by immediately entering Pursat. The history of Koh Sampov Meas is unclear, but it is said that a ship from China came to carry goods around Phsar Krom in Pursat province, but sank and could not be recovered. The water flowed around the sand and became an island. Another story says that Koh Sampov Meas was where she was a servant of Lok Chumteav Khan Khieu, the wife of Duke Khleang Moeung, who jumped into the water to commit suicide with her boss and two other children. But according to the book \"Preah Sdach Kan\" by Dr. Ros Chantrabot, concubine Khieu is the wife of King Chan Reach and she is the maid. Before jumping into the water, she prayed, “I wish I could go to my master and have a monster born in this neighborhood. Penh jumped to her death in the Pursat River near the Lower Market and was born as a monster guarding the mound on the island. Koh Sampov Meas is always visited by tourists throughout the week as it is in town.",
