    "descriptionEn": "Reang Til Pagoda is a pagoda hidden in the forest called Tonle Sap Lake, which has existed since ancient times as a place of worship for Cambodians living on the water to perform Buddhist rituals. The Reang Til area has a floating village where villagers are engaged in fishing, and a flooded forest with a landscape. This area is home to carp and sandalwood, as well as aquatic grasses, which are home to fish during the rainy season.",
