    "descriptionKh": "ភូមិបណ្ដែតទឹកកំពង់ហ្លួងនៅលើទន្លេសាបជាភូមិមួយនៅលើទឹកដែលមានប្រជាជនរស់នៅច្រើនជាង ១ម៉ឺននាក់។ ប្រជាជនគ្រប់រូបរស់នៅលើទូក ហើយភូមិទាំងមូលប្ដូរទីតាំងទៅតាមកម្រិតនៃទឹកបឹង។ ភូមិនេះមានភោជនីយដ្ឋាន សាលារៀន និងរង្គសាលខារ៉ាអូខេផងដែរ។ ទោះបីជាយ៉ាងណា មិនមានកន្លែងស្នាក់នៅទេ តែនៅកំពង់ហ្លួងទេសចរអាចជួលទូកដើម្បីជិះមើលជុំវិញភូមិនោះបាន ដើម្បីយល់ដឹងពីជីវភាពនៅលើទឹក។ នៅរដូវវស្សាវិញ ពិសេសនៅពេលបុណ្យភ្ជុំបិណ្ឌមានប្រជាពលរដ្ឋស្កាត់ ពីទីជិតឆ្ងាយមកកម្សាន្ត ឬក៏ប្រណាំងទូកយ៉ាងសប្បាយរីករាយក្រៃលែង។",
    "descriptionEn": "The floating village of Kampong Luong on the Tonle Sap is a floating village of more than 10,000 inhabitants. Everyone lives on the boat and the whole village moves according to the level of the lake. The village also has restaurants, schools and a karaoke bar. However, there is no accommodation, but in Kampong Luong, tourists can rent a boat to go around the village and understand life on the water. In the rainy season, especially during Pchum Ben, people come from afar to enjoy or have fun with the racing boats.",
