    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "ថ្មកែវជាថ្មកម្រ ហើយត្រូវបានគេនិយមយកមកឆ្លាក់ជាចម្លាក់ផ្សេងៗដូចជាព្រះបដិមា ទេព និងសត្វផ្សេងទៀតទៅតាមពណ៌របស់ថ្ម។ ដោយសារតែចម្លាក់ថ្មកែវមានលក្ខណៈរលោង និងរំលេចនូវក្បាច់យ៉ាងរលូន និងផូរផង់មានមនុស្សជាច្រើនយល់ថា ចម្លាក់ថ្មកែវរបស់ខ្មែរត្រូវបានឆ្លាក់ដោយម៉ាស៊ីនកែច្នៃថ្ម។ តាមការពិតចម្លាក់ថ្មកែវ ពោធិ៍សាត់មិនមែនឆ្លាក់ដោយម៉ាស៊ីនច្នៃថ្មទេ គឺឆ្លាក់ដោយដៃជាងចម្លាក់ខ្មែរ។ ពិតណាស់ថា ពីមុនគេប្រើរណាកាត់ថ្មដោយដៃ តែឥឡូវនេះទំនើបបន្តិចគឺគេកាត់ដោយម៉ូទ័រ ប៉ុន្តែបន្ទាប់ពីនោះ គឺប្រើពន្លាកដាប់ដោយដៃទាំងអស់។ ថ្មកែវមានច្រើនពណ៌ដូចជា ស ទ្រព្យ និងខៀវជាដើម ហើយគេឆ្លាក់ទៅជាសត្វឬវត្ថុតំណាងដោយជ្រើសពណ៌ឱ្យត្រូវទៅនឹងវត្ថុនោះ ដូចជាត្រីហុងស៊ុយត្រូវបានគេប្រើពណ៌ខៀវដែលតំណាងឱ្យភាពត្រជាក់ត្រជុំ។ សិប្បកម្មចម្លាក់ថ្មកែវជាមុខរបរនេះបានកើតមានតាំងពីបុរាណកាលមក ហើយបច្ចុប្បន្ន មុខរបរនេះកាន់តែរីកសាយថែមមួយកម្រិតទៀតសម្រាប់មុខរបរជាលក្ខណៈគ្រួសារ និងមធ្យម។ ទីតាំងដែលមានការប្រកបមុខរបរ និងរចនាម៉ូដថ្មកែវច្រើននោះ គឺនៅក្នុងក្រុងពោធិ៍សាត់ ស្រុកភ្នំក្រវាញ និងស្រុកកណ្ដៀង ដែលភាគច្រើនជាសិប្បកម្មលក្ខណៈគ្រួសារ។ អ្វីដែលកំពុងតែប្រឈមចំពោះសិប្បករ គឺបញ្ហាថ្មឡើងថ្លៃ និងទឹកដៃរចនាម៉ូដរបស់ប្រជាពលរដ្ឋនៅស្ទើរ។",
    "descriptionEn": "Marble is a rare stone and is usually carved into various sculptures such as statues, deities and other animals depending on the color of the stone. Due to smooth stone carvings and smooth and beautiful carvings, many people understand that Khmer marble carvings are carved by stone processing machines. In fact, Pursat marble is not carved by stone machine, but by hand rather than Khmer. It's true that they used to cut the stone by hand, but now it's a bit more modern, they use motor cutting, but after that they use all the cutting tools by hand. Marbles are available in many colors, such as white and blue, and are carved into animals or objects by choosing colors to match the object. For example, Hong shui fish are used blue, which represents freshness. This stone-cutting craft has existed since ancient times, and now it is even more widespread for family and medium-sized businesses. The most popular marble locations and designs are found in Pursat, Phnom Kravanh and Kandieng districts, most of which are family handicrafts. What arises for craftsmen is the problem of rising stone prices and people's design skills.",
