    "descriptionKh": "សារមន្ទីរខេត្តពោធិ៍សាត់ ត្រូវបានសាងសង់ឡើង ដើម្បីរក្សានិងរៀបចំទុកដាក់តាំងនូវវត្ថុបុរាណនានា ដែលប្រមូលបានពីក្នុងខេត្តនិងតំបន់ផ្សេងៗ យកមករក្សាទុកនៅទីនេះ ដើម្បីការថែរក្សាទុកផង និងរៀបចំដាក់តាំងបម្រើភ្ញៀវទេសចរជាតិ និងអន្តរជាតិចូលទស្សនា ដែលនឹងបើកបម្រើពីឆ្នាំ២០២២តទៅ។ ទីតាំងនេះជាអតីតសាលារចនាខេត្ត ដែលផ្ដួចផ្ដើមឡើងដោយសម្ដេចព្រះសីហនុតាំងពីសម័យសង្គមរាស្ត្រនិយមមក។ សារមន្ទីរមានវត្ថុបុរាណជាង ២០០ ដែលរួមមានផ្ដែរ គ្រឿងលំអប្រាសាទ ព្រះបដិមារ និងភាជន៍ ក្រឡ បុរាណ ជាច្រើនផ្សេងទៀត។ ទីនេះមានប្រារព្ធការតាំងពិពណ៌នៅចុងឆ្នាំ២០២១។",
    "descriptionEn": "Pursat Provincial Museum was built to preserve and display artifacts collected from other provinces and regions to be stored here for preservation and display for domestic and international tourists. International tour, which will be open from 2022. This location is a former provincial design school initiated by Prince Sihanouk since the Sangkum era. The museum has over 200 artifacts including relics, temples, statues and many other ancient pottery. The exhibition will be held at the end of 2021.",
