    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តកែវវិជ័យបានត្រូវជ្រើសជាវត្តទេសចរណ៍គំរូ និងមានរបងជាថ្នល់ព័ទ្ធជុំវិញ ប្រកបដោយសមិទ្ធិផលជាច្រើនកុះករពេញក្នុងវត្ត។ វត្តនេះចាប់ផ្ដើមកសាងឡើង តាំងពីឆ្នាំ ១៨៥៩ មក ដោយមានព្រះចៅអធិការដំបូងព្រះនាម កែវ កឹម ហើយក្រោយមកត្រូវបានតែងតាំងជាព្រះមេគណខេត្តពោធិ៍សាត់ផងដែរ។ ក្នុងរបបប៉ុលពតនៅឆ្នាំ១៩៧៥ ព្រះសង្ឃទាំងអស់ត្រូវបង្ខំឱ្យសឹក លុះក្រោយថ្ងៃ ៧មករា ១៩៧៩ ទើបវត្តនេះត្រូវបានបង្កើតឡើងវិញ។ វត្តមានសំណង់ពុទ្ធសាសនាជាច្រើនដូចជា កុដិកម្ពស់២ជាន់ មហាកុដិ បដិមាព្រះអង្គចូលនិពាន្ត សាវ័ក ៩ ទិស ជាដើម។",
    "descriptionEn": "The construction of this pagoda started in 1859 with the first chief abbot, Keo Kem, and later the chief of Pursat province. During the Pol Pot regime in 1975, all the monks were forced to go to war, and it was only after January 7, 1979 that the pagoda was rebuilt. There are many Buddhist buildings, such as the two-storey pavilion, the large pavilion, the statue of the nine directions apostles.",
