    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "អ្នកស្រុកបានប្រទះឃើញរូបបដិមា ដែលឆ្លាក់ជាប់ជញ្ជាំងថ្ម នៅតំបន់ជួរភ្នំក្រវាញកណ្ដាល ដែលទីតាំងនេះ ត្រូវបានប្រជាពលរដ្ឋ និយាយតៗគ្នាថា ជាទីសក្ការៈបូជានាសម័យចេនឡា មុនបុរេប្រវត្តិ និងសម័យអង្គរ។ ប៉ុន្តែតាមការវិភាគតាមរូបរាងនិងទឹកដៃ ចម្លាក់នេះ ធ្វើឡើងក្នុងសម័យកណ្ដាលនោះទេ តែត្រូវធ្វើការសិក្សាបន្ថែមទៀតទើបដឹងពីសម័យកាលនិងកាលបរិច្ឆេទពិតប្រាកដ។ ទីកន្លែងនេះប្រហែលជាតិអាស្រមរបស់លោកធុតង្គ ដែលត្រូវបានបោះបង់យូរហើយ គឺទើបតែរកឃើញនៅឆ្នាំ២០១៩ ទេ។ ទីតាំងស្ថិតនៅជិតរមណីយដ្ឋានភ្នំថ្មស ដែលស្ថាបនាដោយអគ្គិសនីកម្ពុជានិងកំពុងល្បីរន្ទឺផងដែរ។",
    "descriptionEn": "Locals found a stone carving statue in the central mountains of Cardamom, which is said to have been a place of worship in the prehistoric times of Chenla and Angkor. However, according to the analysis of the shape and craftsmanship, this sculpture was made in the Middle Ages, but further studies are needed to know the exact time and date. This place is probably the abode of Thudong, which was abandoned for a long time, was only discovered in 2019. The location is close to the resort of Phnom Thmor Sar, which was built by Electricité du Cambodge and is also very popular.",
