    "descriptionEn": "Traces of the history of the name of the province according to ancient legends that there is a small Po tree drifting along the river along the ancient Pursat River are amazing. Many abbots attempted to reach the Po tree but failed. The last is at the location of Preah Khan, which was later built as a pagoda, Bakan Pagoda, they can be captured using only 7 strands of raw yarn and extracted to plant in the first place, hence the name Po Rath because the word drift And this drift is a single word that can be used interchangeably. After a long time, it became Pursat, the name of the province. The old Po tree died, but today many Po seedlings are growing on the hill. Relics from history are also plentiful here, such as fragments of pillars, sculpted heads with bells and marble eyes. Apart from this, there are also laterite pillars, thrones and main gates made of sandstone. It should be noted that since Bakan Pagoda has",
