    "descriptionKh": "នៅបូជនីយដ្ឋានប្រវត្តិសាស្រ្តលោកតាឃ្លាំងមឿងស្ទើរពេញមួយសប្ដាហ៍មិនដាច់ភ្ញៀវឡើយ ពិសេសនៅថ្ងៃសីលដោយពួកគាត់ភាគច្រើនជាអ្នកទៅបែរបន់សុំសេចក្ដីសុខសប្បាយពីបារមីអ្នកតាមេទ័ព។ ទាក់ទងនឹងអ្នកតាឃ្លាំងមឿងមិនមានរូបរាងបែបឈើឬថ្មជាតំណាងទេ គឺជាតួដីដំបូកសុទ្ធៗ ទំហំបណ្ដោយ ២ ម៉ែត្រ ទទឹង ១ ម៉ែត្រ កម្ពស់ ២ ម៉ែត្រ ដែលកើតអំពីសត្វកណ្ដៀរពូនឡើង។ ប្រវត្តិនៃអ្នកតាឃ្លាំងមឿងនេះគឺ ក្នុងសម័យដែលស្រុកខ្មែរជាស្រុកចំណុះសៀមក៏មានការបះបោរសម្លាប់ព្រះរាជបុត្រព្រះចៅសៀម ធ្វើឱ្យព្រះចៅសៀមលើកទ័ពមកសងសឹក ដោយសម្លាប់ព្រះរាជានិងញាតិសាច់សាលោហិតព្រមទាំងពួកមន្ត្រីផង។ សៀមបានរិបជាន់យកទ្រព្យសម្បត្តិនិងកៀរបណ្ដារាស្ត្រដោយទាំងព្រះម្នាងជាស្នំមានគ័ភ៌ និងមេដំរីសមួយក៏មានគ័ភ៌ដែរទៅស្រុកសៀម។ លុះព្រះម្នាងមានគភ៌គ្រប់ខែក៏ប្រសូតបុត្រមក ឈ្មោះឧទេន ហើយមេដំរីក៏កើតកូនក្នុងថ្ងៃតំណាលគ្នានោះដែរ។ កុមារឧទេនខំរៀនសូត្រវិជ្ជាគ្រប់យ៉ាងនិងវិជ្ជាខាងហ្មដំរីផងដែរ។ ថ្ងៃមួយដំរីកូននោះចុះប្រេងមិនមានអ្នកឯណាបង្ក្រាបបាន មានតែកុមារឧទេនទើបអាចចាប់ដំរីនោះបាន ទើបព្រះចៅសៀមក៏ប្រទានរង្វាន់និងងារឱ្យថា ជ័យអស្ចារ្យ។ លុះដល់អាយុ ១៦ ឆ្នាំ ជ័យអស្ចារ្យក៏នឹករកឧបាយដោះខ្លួនចេញអំពីសៀម ដោយចាត់មនុស្សធ្វើជាលនិងឈើជើងដំរីបន្លំជាដានជើងដំរីធំមួយ។ ព្រះចៅសៀមក៏ប្រើជ័យអស្ចារ្យទៅតាមទាក់ដំរីព្រៃនោះ ទើបជ័យអស្ចារ្យបានលេសសុំគ្នីគ្នានឹងដំរីធ្នាក់ច្រើនទៀតធ្វើដំណើរមកដល់ស្រុកបាត់ដំបង។ នៅទីនោះមានអ្នកស្រុករត់មកចុះចូលថ្វាយខ្លួនជាពលសេនា រួមទាំងសេនាចាស់ម្នាក់ឈ្មោះ មឿងនិងកូនប្រុស៤ នាក់ផងដែរ។ ព្រះចៅសៀមទ្រង់ព្រះពិរោធយ៉ាងខ្លាំងពេលដឹងថាជ័យអស្ចារ្យក្បត់ក៏លើកទ័ពមកកម្ចាត់។ ពេលជំនុំនិងពលសេនារកវិធីទប់ទល់ទ័ពសៀមនោះ មានតែសេនាមឿងឆ្លើយអះអាងហ៊ានតទល់ ដោយសុខចិត្តទៅកែនពលខ្មោចមកជួយច្បាំង។ គាត់បង្គាប់ឱ្យជីករណ្ដៅរួចឱ្យដាក់គ្រឿងសស្ត្រាវុធក្នុងរណ្ដៅនោះដើម្បីនឹងលោតទៅឱ្យជង់ស្លាប់ក្នុងរណ្ដៅ ហើយបានផ្ដាំថា បើខ្ញុំស្លាប់ទៅបាន៧ថ្ងៃឮសូរសន្ធឹកហ៊ោកញ្ជ្រៀវយើងនឹងមានជ័យហើយ។ លុះផ្ដាំរួចក៏លោតចុះទៅក្នុងរណ្ដៅ ទាំងប្រពន្ធនិងកូនប្រុសពីរនាក់ស្លាប់ជាមួយគ្នា។ ដល់គ្រប់៧ថ្ងៃក៏លាន់ឮសូរសន្ធឹកដូចគាត់ផ្ដាំមែន ហើយទ័ពខ្មោចចេញសម្ដែងឫទ្ធិធ្វើឱ្យពលសៀមដកថយត្រឡប់ទៅវិញអស់។ ស្ដេចនឹកឃើញដល់គុណូបការៈសេនាមឿង ក៏ចាត់ឱ្យធ្វើបុណ្យឧទ្ទិសផលយ៉ាងឧឡារិកអស្ចារ្យ ជាប់ជាទំនៀមដរាបមកដល់មកសព្វថ្ងៃនេះ ហៅថាធ្វើបុណ្យឡើងអ្នកតាឃ្លាំងមឿង។",
    "descriptionEn": "At the historical monument, Grandfather Khleang Moeung has no shortage of guests for most of the week, especially on Shabbat, as most of them go to ask the commandant for peace. Regarding Neak Ta Khleang Moeung, there is no wooden or stone form as a representative, it is a pure mound body, 2 meters long, 1 meter wide, 2 meters high, which is caused by termites. The story of Khleang Moeung is that when Cambodia was a Siamese province, there was an uprising to kill the Siamese son, which caused the Siamese king to take revenge by killing the king and his parents and officials of blood. The Siamese confiscated property and took the people, including a pregnant princess and a pregnant elephant to Siam. When she became pregnant, she gave birth to a son named Uten, and the mother gave birth the same day. The Uten children try to learn all kinds of subjects and the subject of elephant tusks as well. One day the baby elephant went down in the oil, no one could restrain him, only the child Uten could catch the elephant, so the Siamese king gave him a reward and a title of great victory. When he was 16, Chey Aschar thought of a way to free himself from Siam by sending people to be elephants and imitating elephant feet as a footprint of a large elephant. The Siamese king also used the big win to catch the wild elephant, so the big win served as an excuse to ask for more elephants to go to Battambang district. There, locals rushed to surrender as soldiers, including an old soldier named Moeung and his four sons. The Siamese king was very angry when he learned that the great victory betrayed the army to be defeated. When the Church and the Army found a way to resist the Siamese Army, only Sena Moeung responded and dared to fight of his own free will to go to the Shadow Army to help fight. He ordered them to dig a pit and put weapons in the pit to jump to their death in the pit and warned that if I died seven days later we would be victorious. He jumped into the pit and his wife and two sons died. After seven days, he heard a loud voice as he had warned him, and the ghost army came out to show their might, causing the Siamese troops to retreat. The king remembered the merits: Sena Moeung also sent a solemn dedication ceremony, which has been a tradition until today, called the Neak Ta Khleang Moeung festival.",
