    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តនេះត្រូវបានកសាងក្នុងសម័យសង្គមរាស្ត្រនិយមហើយក៏បានជួសជុលឡើងវិញ។ អារាមវត្តស្បូវរីក ជាអតីតមន្ទីរពេទ្យប្រចាំសហករណ៍លាជ ក្នុងសម័យកម្ពុជាប្រជាធិបតេយ្យដែលជាវត្តដ៏ចំណាស់ ដែលស្ថិតជិតទីប្រជុំជនស្រុកភ្នំក្រវាញតែម្ដង។ ព្រះវិហារវត្តស្បូវរីក សង់ឡើងពីសសរឈើ ដែលគិតមកដល់ពេលនេះ មានអាយុកាលយូរឆ្នាំជាងគេនៅក្នុងខេត្ត។ អាស្រ័យដោយកាលវេលាច្រើនទសវត្សរ៍កន្លងមកនេះ បូកផ្សំនឹងកង្វះការថែទាំ ទើបធ្វើឱ្យសសរឈើដែលស្ថិតនៅមួយជុំខាងក្រៅព្រះវិហារ ត្រូវបានរងនូវការពុកផុយពីធម្មជាតិស្ទើរតែទាំងអស់។ គឺព្រះវិហារនេះហើយ ដែលអង្គការខ្មែរក្រហម បានប្រែក្លាយឱ្យទៅជាអគារស្នាក់នៅរបស់អ្នកជំងឺ ហើយសព្វថ្ងៃវត្តនោះក៏ជាប់ក្នុងចំណោមវត្តទេសចរណ៍ផងដែរ។",
    "descriptionEn": "This pagoda was built during the Sangkum Reastr Niyum era and has also been renovated. Sbov Rik Pagoda is a former hospital of Leach Cooperative in the days of Democratic Kampuchea, an ancient pagoda near Phnom Kravanh town. Sbov Pagoda is made of the oldest wooden pillars in the province. Due to the past decades, combined with lack of maintenance, the wooden pillars outside the church have suffered almost all natural decay. It was this church that the Khmer Rouge turned into a shelter for patients, and today it is also one of the tourist attractions.",
