    "descriptionKh": "ទីពិឃាតនេះជាកន្លែងដែលពួកខ្មែរក្រហមបានប្រមូលយកទាហាន និងអ្នករដ្ឋការនៃរបបសាធារណរដ្ឋលន់នល់ជាច្រើនយកមកសម្លាប់។ រណ្ដៅសាកសពជាច្រើនត្រូវបានគេប្រទះឃើញ ដែលជាកន្លែងសម្លាប់អំឡុងឆ្នាំ ១៩៧៥ ដែលតាមរបាយការណ៍មានជនរងគ្រោះប្រមាណជាង ១០ពាន់នាក់។ នៅលើទីទួលនេះ មានសាងសង់សាលាបុណ្យមួយ ផ្ដួចផ្ដើមគំនិតដោយជំទាវ ភឿង សកុណា ជារដ្ឋមន្ត្រីក្រសួងវប្បធម៌និងវិចិត្រសិល្បៈ ដែលមានឪពុក ជានាយទាហានរបបសាធារណរដ្ឋ ហើយត្រូវបានសម្លាប់នៅទីនេះ។ ក្នុងសាលាបុណ្យនោះ មានផ្ទាំងចារឹករំលឹកដល់ជនរងគ្រោះទាំងនោះផងដែរ។",
    "descriptionEn": "The massacre was where the Khmer Rouge recruited and killed many Lon Nol soldiers and administrators. Graves have been found at the scene of the massacre in 1975, with more than 10,000 victims declared dead. On this hill, a school was built on the initiative of Mrs. Pheung Sakona, Minister of Culture and Fine Arts, whose father was an officer in the Republican army and was killed here. The school also has a plaque commemorating the victims.",
