    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "អដ្ឋិធាតុ ដែលបានគាស់ចេញពីទីតាំងសម្លាប់កូនត្នោត វាលតារាងបាល់ និងខាងលិចសាលារៀនភូមិរំលេច ត្រូវនាំយកមកដាក់តម្កល់នៅក្នុងបរិវេណវត្តនេះ ដើម្បីទុកធ្វើជាទីសម្រាប់គោរពវិញ្ញាណក្ខន្ធអ្នកដែលបានចែកឋានទៅ និងជាកន្លែងរំឭកទិវាថ្ងៃ២០ ឧសភា។ កាលពីឆ្នាំ១៩៧៩ ប្រជាជន និងរដ្ឋអំណាចមូលដ្ឋានបាននាំគ្នាជីកកកាយរណ្ដៅសាកសពរួមនៅតាមទីតាំងខាងលើ ហើយបង្កើតបានជាមន្ទីរបូជនីយដ្ឋាននេះ ប៉ុន្តែតាមសង្ឃដីការរបស់ ព្រះសង្ឃគង់នៅក្នុងវត្តរំលេចបានឱ្យដឹងថា អដ្ឋិធាតុដែលតម្កល់ទាំងប៉ុន្មាន ត្រូវតាជី និង យាយជីប្រមូលកប់ដីអស់ខ្លះហើយ។",
    "descriptionEn": "The remains of the slaughterhouse, the football field and west of the school from the village of Romlech will be brought to the pagoda to be kept as a place of remembrance for those who died and as a place to commemorate the day. In 1979, local people and local authorities dug a mass grave at the site and erected a monument, but according to the order of the monks of Romlech Pagoda, the remains were found. Ta Chi and Yai Chi have already collected burial sites.",
