    "id": "rac-k16042",
    "nameKh": "ល្អាងភ្នំគំនូរបុរាណ",
    "nameEn": "Antique Mountain Cave with paintings",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "តាមការបញ្ជាក់របស់លោក លឹម វណ្ណច័ន្ទ ប្រធានការិយាល័យ នៃនាយកដ្ឋានតំបន់បេតិកភណ្ឌ និងជាអ្នកជំនាញបុរាណវិទ្យា បានឲ្យដឹងថា គំនូរក្នុងល្អាងនេះ ជាគំនូរដែលមានវ័យចំណាស់ ប៉ុន្តែយើងក៏មិនហ៊ានសន្និដ្ឋានថា អាយុកាលប៉ុន្មាននោះទេ ពីព្រោះការឲ្យអាយុទៅលើស្នាដៃសិល្បៈមួយ យើងត្រូវតែមានការសិក្សា ដែលមានការចូលរួមពីអ្នកបច្ចេកទេស និងការសិក្សាស្រាវជ្រាវបែបវិទ្យាសាស្ត្រ។ គំនូរនៅក្នុងល្អាងនេះ គឺគេគូរប្រើប្រាស់ថ្នាំប្រភេទពណ៌ក្រហម និងមានស្នាមឆ្កូតខ្លះ ដើម្បីឲ្យចេញជារូបរាង។ អ្វីដែលសំខាន់ គឺយើងឃើញរូបពាក់ព័ន្ធនឹងសត្វព្រៃ ដូចជា ដំរី ក្ដាន់ ប្រើស ជ្រូកព្រៃ ជាដើម។ ការគូរ មិនមានលក្ខណៈល្អ ឬច្បាស់អ្វីទេ ប៉ុន្តែវាគឺជាចំណុចពិសេសមួយ នៃតំបន់ភ្នំក្រវាញកណ្ដាលនេះ ដែលបង្ហាញពីជីវិតប្រជាជន ដែលគាត់ចេះប្រើប្រាស់ដំរី ជាមួយនឹងការរស់នៅជាមួយសត្វព្រៃ ដែលមាននៅក្នុងតំបន់ដែលពួកគាត់រស់នៅ។ ល្អាងគំនូរនេះ នឹងអាចជួយជំរុញឲ្យអ្នកសិក្សាស្រាវជ្រាវពីបុរេប្រវត្តិ និងការធ្វើកំណាយ ឲ្យបានច្បាស់ពីអាយុកាល ហើយល្អាងគំនួរនេះ អាចទាក់ទាញភ្ញៀវទេសចរណ៍ ដែលចូលចិត្តលម្ហែតាមតំបន់ការពារធម្មជាតិ ហើយនឹងស្វែងរកនូវកន្លែងប្លែកៗ មកកម្សាន្តតាមបែបធ្វើដំណើរផ្សងព្រេងផងដែរ។",
    "descriptionEn": "Mr. Lim Vanchan, director of the heritage department office and archaeologist, to confirm that the paintings in this cave are ancient paintings, but we dare not conclude how old, because to give age to a work of art requires a study that involves the participation of technicians and scientific research. The paintings in this cave are painted with red paint and have some scratches to make it look like. The important thing is that we see images related to wildlife like elephants, deer, stags, boars, etc. The painting is not very good or clear, but it is a peculiarity of this central region of Cardamom that shows the life of people who know how to use elephants and live with the fauna of the region where they live. . This cave will inspire you to study the prehistory and the excavations of the time, and this cave can attract tourists who like to relax in the protected area and find a different place to visit. Also go on an adventure trip.",
