    "descriptionKh": "ប្រាសាទមានឈ្មោះផ្សេងទៀតដូចជា ប្រាសាទព្រៃជើងស្រុក, ព្រៃចុងស្រុក, ព្រះធាតុរាជមន្ទីរផងដែរ។ ឈ្មោះទាំងនេះប្រហែលជាល្អៀងដោយការកត់សូររបស់បារាំងរវាងពាក្យ «ជើង» និង «ចុង» តែអ្នកស្រុកនិយមហៅថា ដើមស្រុក គឺមានន័យប្រហែលនឹង ជើងស្រុក គឺព្រៃចាប់ផ្ដើមពីទីនេះទៅ។ ប្រាសាទឥដ្ឋនាសម័យពាក់កណ្ដាលសវ.ទី៧ និងទី៨ និងក្រោយមកនាសម័យអង្គរក្នុងកំឡុងស.វ.ទី១០ មានការកែលម្អឡើងវិញ។ ប្រាសាទមានកំពស់ប្រមាណ ១៣ ម៉ែត្រ គិតទាំងផ្នែកដែលកប់ក្នុងដី និងទំហំជាង ៥ ម៉ែត្រ ៤ ជ្រុង ហើយស្ថិតលើទួលមួយមានទំហំប្រមាណជា ១០០ ម៉ែត្រ។ ប្រាសាទមានប្រាង្គតែមួយ បែរទៅទិសខាងកើត មានទ្វារបញ្ឆោត៣ នៅជ្រុងផ្សេងទៀត។ បា្រសាទនេះព័ទ្ធជុំវិញទៅដោយសិន្ធុ មានសសរពេជ្រ មេទ្វារ និងផ្ដែរ សោមសូត្រ ជើងទម្រសាងពីថ្មភក់ និងថ្មថ្លើមអណ្ដើក (ថ្មស៊ីសឬថ្មស្រទាប់)។ ប៉ុន្តែតាមការសង្កេត អាចមានប្រាង្គច្រើនទៀត ដែលដួលរលំ ហើយត្រូវបានគ្រប់ពីលើដោយសំណង់ថ្មី។ ទីនេះជាប្រភពសិលាចារឹកលេខ K761 ដែលត្រូវបានយកទៅតម្កល់នៅសារមន្ទីរជាតិ ហើយមានផ្ដែរដែលឆ្លាក់មិនទាន់រួច និងសសរពេជ្ររាងមូល។ យោងតាមសិលាចារឹកនេះបញ្ជាក់កាលបរិច្ឆេទ ឆ្នាំ៥៥៥ សក. ដែលត្រូវឆ្នាំ៦៣៣គ.ស. នៅចុងរាជ្យរបស់ព្រះបាទស្រីឦសានវម៌្មន។ ប៉ុន្តែអត្ថសិលាចារឹក២ ជ្រុងទៀតអក្សរបែបសម័យអង្គរវិញ ដែលជាតង្វាយមូលនិធិរបស់ព្រាហ្មណ៍ ឈ្មោះថា ស្រីធរស្វាមិ រួមជាមួយ ក្រឹស្នហរ មានដូចជា បារាយណ៍ទឹក និងបង្គោលព្រំសីមា។ បន្ទាប់មកទៀតជាពាក្យបណ្ដាសាដល់ជនណា ដែលបានបំពារបំពានយកទ្រព្យសម្បត្តិរបស់ទេវស្ថាន ឱ្យស្លាប់ទៅត្រូវរងទុក្ខនៅស្ថាននរក។",
    "descriptionEn": "There are several names of this temple: Prey Cheurng Srok temple, Prey Chong Srok temple, Preah Theat Reach Monty. These names may be biased because of the recording sounds of the French between “Cheurng”and “Chong”. Yet, local people called this place as “Doeum” which has the similar meaning to “Cheurng Srok” since the forest is widely located there. The brick temples in the mid-7th and 8th centuries, and later in the Angkorian period during the 10th century AD were restored. The temple is about 13 meters high, including the part buried in the ground and more than 5 meters square and on a hill about 100 meters. The temple has a single tower facing east, with three false doors at the other corners. This temple is surrounded by moat, colonette, main door and a lintel, \"soma Sotra\", sandstone pedestal and black basalt (dolomite). But according to observation, there may be more towers that have collapsed and are covered by new construction. Here is the source of the inscription number K761, which is kept at the national museum and has an unfinished carved pedestal and a round colonette. Referring to this inscription, the date was proved in 555 A.D. which corresponds to the year 633 A.D. at the end of the reign of King Srey Isanvarman. However, the other two inscriptions of the Angkorian script, offered the Brahmins named Srey Thor Swami, along with \"Krisna Hara\", which consists of water bar (Baray Teuk) and the boundary pole. Then there were words of curse on any person who abused the property of god to sufferingly die in hell.",
