    "descriptionKh": "រមណីដ្ឋានប្រវត្តិសាស្ត្រនេះជាសំណង់បុរាណ ព្រមទាំងជាកន្លែងគោរពបូជាមួយដ៏ល្បីនៅក្នុងខេត្តព្រៃវែង។ ប្រាសាទជាកន្លែងទេសចរណ៍ល្អបំផុតនៅក្នុងខេត្តព្រៃវែងនេះ ដោយនៅទីនោះ មានការគោរពបូជាបែបជំនឿអរូបីដែលត្រូវបានគេទៅទស្សនាជាញឹកញាប់។ ប្រាសាទនៃសម័យបុរេអង្គរ ហើយនៅសម័យអង្គរត្រូវបានសាងសង់បន្ថែម ដើម្បីឧទ្ទិសដល់ព្រហ្មញ្ញសាសនា និងក្រោយមកបានកែប្រែជាសំណង់ព្រះពុទ្ធសាសនាវិញ។ ទីនេះជាប្រភពសិលាចារឹកលេខK58,K59។ ទីនេះជាប្រភពសិលាចារឹកលេខ K58 ចារឹកនៅស.វ.ទី១០និងសិលាចារឹកលេខK59 ចារឹកនៅក្នុងឆ្នាំ ១៨៧៧។ លោកសឺដេសធ្លាប់សន្និដ្ឋានថា ជារាជធានីរបស់ណន ឈ្មោះវ្យាធបុរ ប៉ុន្តែក្រោយមកអ្នកស្រាវជ្រាវផ្សេងៗយល់ថានៅអង្គរបុរីវិញ។",
    "descriptionEn": "This ancient historical resort is an ancient building and a famous worship place in Prey Veng province. This temple is classified as one of the best tourist sites in Prey Veng province since it attracts more tourists to often visit and superstitiously worship. The temple was noted as a temple of pre-Angkorian era, and the instruction was enhanced and added in Angkorian era in the purpose of dedication to Brahmanism, which later converted the construction of Buddhism. Here is the source of the inscription K58, K59. Here is the source of the inscription K58, written in the 10th century CE, and the inscription K59, inscribed in 1877. Mr. Cedes used to conclude that it was the capital of Nan named Vyathapura, but later other researchers thought it was Angkor Borei.",
