    "descriptionKh": "វត្តមានឈ្មោះល្បីដោយសារជាទីដែល នេនទុំ បានបួសរៀនហើយចាកសិក្ខាបទដោយចិត្តឯងនៅទីនេះ។ «ទុំទាវ»ជាប្រវត្តិស្នេហាដែលបញ្ចប់ដោយមរណភាពនៃតួអង្គទាំងពីរ។ ក្នុងវត្តនេះមានរក្សាទុក ដើមពោធិ៍ដួលរលំ ដែលដាំដោយព្រះគ្រូ ម៉ី ជាគ្រូរបស់នេនទុំ និងដំបូកថ្មបាយក្រៀមមួយ ដែលគេជឿថា ជាកន្លែងដែលនេនទុំចាកសិក្ខាបទដោយចិត្តឯង។",
    "descriptionEn": "This place is famous since it was where a novice named Tum became a monk and left the monkhood. “Tum Teav” is the love story which ended up by the death of the two main characters. In the area of the pagoda, the fallen banyan tree planted by Tum’s teacher named Mey, and laterite mound believed to be a place where Tum monkhood by himself.",
