    "descriptionEn": "Borha Poit Kod Rarm Pagoda, known as Kompoul Chheu Kach, was built in 1936 on the mountain-top of Phnom Toch in Chheu Kach village. Before 1975, the leaf-roof Buddhist temple was transformed to the tilt-roof temple; additionally, some new constructions have been built too. From 1975 to 1979, the Khmer Rouge destroyed this religious site and forced the monks to leave their monkhood. Nowadays, there are more new constructions in the area of this pagoda. This pagoda has been proposed to be a tourism site.",
