    "descriptionEn": "The pagoda was built in 1885 based on the location of the hill, which was originally inscribed with the name of Ta Daun Yeay Sdeurng. From 1975 to 1979, the Khmer Rouge destroyed almost all the places in the pagoda and severely tortured the monks. From the liberation on January 7, 1979 to the present, the pagoda was re-established in 1981 and built constructions which now it becomes one of the tourism sites in the region.",
