    "id": "rac-k17011",
    "nameKh": "វត្តព្រៃវៀរ, វត្តសុរិយោវង្ស",
    "nameEn": "Prei Vea Pagoda",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តមានឈ្មោះដើមថា សុរិយាវង្ស សាងសង់ឡើងក្នុងឆ្នាំ ១៦៦៤ (ព.ស ១២២៤) ។ វត្តនេះជាអារាមព្រះពុទ្ធសាសនាមួយ ដែលបានសាងសង់ឡើងនៅលើទីតាំងប្រាសាទចាស់ក្នុងកំឡុងស.វ.ទី៧ សព្វថ្ងៃនៅមានសេសសល់បុរាណវត្ថុមួយចំនួនផងដែរ។ វត្តនេះជាប្រភពសិលាចារឹកលេខ K49 (បាត់) និង K50 (នៅសារមន្ទីរជាតិក្រុងភ្នំពេញ)។ យោងតាមសិលាចារឹក ទាំងពីរដែលចុះកាលបរិច្ឆេទឆ្នាំ៥៨៦ និង ៥៩០ ម.ស ពណ៌នាពីអំភិក្ខុសង្ឃ២អង្គ ជារាជត្រកូលបងប្អូនបង្កើតនិងគ្នា គឺ ភិក្ខុរតនៈភាណុ និង ភិក្ខុរតនៈសិង្ហ ក្នុងរជ្ជកាលព្រះបាទជយវរ្ម័នទី១ នៅក្នុងទីក្រុងនរវរនគរ ដែលសាងព្រះផ្នួសនៅទីនេះ។ ឆ្នាំ ១៩៧៥ ដល់ឆ្នាំ ១៩៧៩ វត្តត្រូវបានខ្មែរក្រហមបំផ្លិចបំផ្លាញ ហើយបច្ចុប្បន្នវត្តមានទីសេនាសនៈដ៏វិចិត្រ និងក្លាយជាវត្តទេសចរណ៍។",
    "descriptionEn": "The former name of the pagoda is Soriyovong, built in 1664 (1224 B.E). This pagoda was built on an old location of a temple in the 7th century, which some artifacts are seen. This pagoda is the place of the inscription K49 (lost) and K50 (in the national museum in Phnom Penh). According to both steles of the inscriptions dated in Moha Sakha year 586 and 590 inscribed about two monks who are brothers: Bhikhu Rattanak Pheanu and Bhikhu Rattanak Singh became monks in this pagoda during the reign of the King Jay Varman I in Narak Vorak Nokor. From 1975 to 1979, this pagoda was destroyed by the Khmer Rouge. Nowadays, this magnificent pagoda has been proposed to be a tourism site.",
