    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "អ្នកតានេះមានប្រវត្តទាក់ទងរឿងព្រេងស្ដីពី«ម្ចាស់ក្សត្រីជនជាតិក្រិក?» នាម នារីផល ដែលមកតាមសងសឹកជួសស្វាមីដែលជាព្រះអង្គម្ចាស់ពីនគរភ្នំបានទៅសិក្សារៀនសូត្រនៅប្រទេសក្រិក។ ទីនោះមានភ្នំមួយតូចស្ថិតនៅក្បែរមាត់ព្រៃ កម្ពស់ប្រមាណជា ១០ម. ដែលនៅចន្លោះនៃថ្មភ្នំធំៗ ជារោងអ្នកតា មានបដិមាបី។ អ្នកតានេះពីសម័យដើមគេយកមនុស្សទោសអស់ជីវិតមកបូជាយញ្ញ ប៉ុត្តែចំណេរក្រោយមកគេបូជាក្របី ហើយសព្វថ្ងៃនេះគឺត្រឹមជ្រូកខ្វៃប៉ុណ្ណោះ។ ពិធីត្រូវធ្វើក្រោមវត្តមានអភិបាលស្រុក ដែលមានតំណមមិនមកកាន់ទីនេះ៧ថ្ងៃមុនប្រារព្ធពិធី។",
    "descriptionEn": "This guardian spirit has a history related to the legend of \"Greek princess?\" named Neary Phal, who came in revenge for her husband, the prince from Nokor Phnom (Mountain Kongdom), went to study in Greece. There is a small mountain, about 10 meters high, near the edge of the forest. In the middle of the big rocks, there are three statues of Neak Ta. In the past, dead sentenced people were sacrificed, but later buffaloes, and today pigs are used to offer in the sacrifice. The ceremony is happened under the presence of district governor who is forbidden not to be at place seven days before the ceremony takes place.",
