    "id": "rac-k17014",
    "nameKh": "ឆ្នេរខ្សាច់ដីដុះ",
    "nameEn": "Dei Dos Resort",
    "categorySlug": "beach",
    "categoryKh": "កោះ & ឆ្នេរសមុទ្រ",
    "categoryEn": "Islands & Beaches",
    "descriptionKh": "ឆ្នេរខ្សាច់ដីដុះជាទីតាំងរមណីយដ្ឋាននាមាត់ទន្លេ ដែលកំពុងពេញនិយមសម្រាប់ងូតទឹកលេងកម្សាន្តរបស់ ប្រជាពលរដ្ឋ ក៏ដូចជាភ្ញៀវទេសចរជាតិ និង អន្តរជាតិដែលបានទៅដល់ទឹកដីខេត្តព្រៃវែងនេះ ។ ឆ្នេរខ្សាច់ កន្លែងកម្សាន្តដីដុះនេះមាន ដីខ្សាច់ដុះចេញពីក្នុងទន្លេចាប់ពីមាត់ច្រាំងរហូតដល់កណ្ដាលទន្លេ និង លាតសន្ធឹងយ៉ាងល្វឹងល្វើយតាមបណ្ដោយ ដងទន្លេមេគង្គចម្ងាយប្រមាណ ជាង ២ គីឡូម៉ែត្រ ។ ក្រៅពីងូត ទឹកកម្សាន្ត ភ្ញៀវទេសចរអាចលេងកីឡា រាំលេងកម្សាន្ត និង ធ្វើពិធីជួបជុំផ្សេងៗជាមួយនឹងការទទួលទានម្ហូប អាហារ ដ៏មានឱជារសគ្រប់ប្រភេទដែលមានលក់នៅលើឆ្នេរខ្សាច់ ជាពិសេសភ្ញៀវ ទេសចរអាចបើកយាន ជំនិះរបស់ខ្លួនចូលទៅដល់មាត់ទឹកដែលនៅកណ្ដាល ទន្លេតែម្ដង ។ ដោយសារកត្តាអំណោយផលពីធម្មជាតិ បែបនេះទើបធ្វើឱ្យភ្ញៀវទេសចរទាំងជាតិ និង អន្តរជាតិចូលចិត្តនាំក្រុមគ្រួសារ ទៅងូតទឹកលេង កម្សាន្តនៅ តំបន់ដីដុះនេះ ជាពិសេសនៅរដូវបុណ្យទាន ដូចជាថ្ងៃបុណ្យភ្ជុំបិណ្ឌ និង ថ្ងៃចូលឆ្នាំជាដើម ជាក់ស្តែងនៅ រយៈពេល ៣ ថ្ងៃ នៃពិធីបុណ្យ ចូលឆ្នាំខ្មែរ ភ្ញៀវទេសចរទាំងជាតិ និង អន្តរជាតិបាននាំគ្នាទៅងូតទឹកលេង កម្សាន្តនៅតំបន់ដីដុះនោះមានចំនួនរហូតដល់ទៅរាប់ម៉ឺននាក់ ដោយសារតែទីនេះមានភាពទាក់ទាញ។",
    "descriptionEn": "Dei Dos coast is a popular riverside resort for bathing and entertaining local as well as visitors to Prey Veng province. The sandy coast extends from the bank to the middle of the river and stretches along the river for more than 2 km. Besides bathing, visitors are able to play sports, dance on the sandy riverside; especially, visitors can drive to the nearest part of the riverside. On festive seasons, this resort can attract thousands of visitors to enjoy various activities.",
