    "descriptionEn": "Located north of Beong Sneh, this protected area is rich in millions of birds such as Asian openbill, herons, pelicans, ibises and so on. The nature protected area covers an area of more than 80 hectares and the water area is 3,000 hectares, which is a large lake, sparse forest and flooded jungle. The protected area of Boeung Sneh was founded in 2012 under the support of Women Organization in the purpose of conservation of endangered species of birds, which are trapped and poached by the locals at night.",
