    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "«កម្ពោជិកបុត្តាខេមរាតរី» មានន័យថា «ទូកងរបស់កូនខ្មែររស់នៅក្នុងដែនដីកម្ពុជា» មានបណ្ដោយប្រវែងជាង ៨៧,៤៧ ម៉ែត្រ ទទឹងប្រមាណជិត២ម៉ែត្រ ជម្រៅ០,៨០ម៉ែត្រ និងផ្ទុកចំណុះមនុស្សបានចំនួន១៧៩នាក់។ ទូកងនេះបានរក្សាទុកនៅជិតទួលបារាយអណ្ដែត ហើយជាទូកងដែលជាប់កំណត់ត្រាពិភពលោក World Guinness Record នេះ ត្រូវបានរចនាឡើងដោយផ្នែកខាងក្បាលទូកធ្វើជាក្បាលនាគ និងកន្ទុយហង្ស ប្រកបដោយក្បូរក្បាច់រចនាល្អប្រណីត ឈ្នះកំណត់ត្រាពិភពលោកចាស់ទូកនាគរបស់ប្រទេសចិន ដែលមានប្រវែង៧៧,៨០ម៉ែត្រ។",
    "descriptionEn": "«Kampuchik Botta Khemaratrey» means “the racing boat of Khmer in Cambodia territory”. It is more than 87.47 meters long, about 2 meters wide, 0.80 meters deep, and can accommodate 179 people. This racing boat is kept near Toul Baray Andet, and it was recorded in the World Guiness Record. This boat was designed with a dragon head, a swan tail and aesthetic decor, which claimed to win the elaborate design of the 77.80-meter-long Chinese dragon boat's old-world record.",
