    "id": "rac-k17019",
    "nameKh": "ភ្នំឈើកាច់, នគរភ្នំ",
    "nameEn": "Cheu Kach Mountain",
    "categorySlug": "nature",
    "categoryKh": "រមណីយដ្ឋានធម្មជាតិ & កែច្នៃ",
    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "រមណីយដ្ឋានបាភ្នំ មានភ្នំ ៤ នៅម្ដុំគ្នា គឺ ភ្នំសំពៅ ភ្នំល្អាង ភ្នំធំ និងភ្នំបញ្ជារ។ បាភ្នំ ជាអតីតរាជធានីចាស់ឈ្មោះថា «នគរភ្នំ» ស្ថិតនៅក្បែរភ្នំទាំងឡាយក្នុងស្រុកបាភ្នំ ដែលបច្ចុប្បន្ននៅបន្សល់ស្នាមខ្លះៗប៉ុណ្ណោះ ដូចជាប្រាសាទបុរាណមួយឈ្មោះថា ប្រាសាទច័ន្ទ ស្ថិតនៅចំពីមុខវត្តវិហារគុកក្បែរជើងភ្នំសំពៅ ក្នុងឃុំជើងភ្នំ។ ឯមន្ទីរ និងរាជវាំងនានាត្រូវបាក់បែករូបរាងដោយនគរភ្នំជំនាន់នោះមានសង្រ្គាម។ បាភ្នំមានទេសភាពល្អត្រកាល កាលណាយើងឡើងដល់កំពូលភ្នំមើលមកក្រោម និងមានផ្ទាំងថ្ម រូងថ្មធំៗ ដែលជាដែនជំរកសត្វព្រៃមួយចំនួនលាក់ខ្លួនបាន។ នៅជើងភ្នំមានវត្តឈ្មោះថា «វត្តភ្នំ» ឬ «វត្តបាភ្នំ»។ រមណីយដ្ឋានបាភ្នំជារមណីយដ្ឋានកែច្នៃមានផ្លូវ និងសំណង់ប្រាសាទថ្មីមានក្បាច់ចម្លាក់បុរាណព័ទ្ធជុំវិញភ្នំ ប្រកបដោយជណ្ដើរ ពីរនិងអាស្រមនានាផងដែរ។",
    "descriptionEn": "Ba Phnom Resort consists of four mountains together: Sampoev mountain, La’ang mountain, Thom mountain, and Banchea mountain. Ba Phnom is a former capital named “Nokor Phnom” Ba Phnom, the former capital of \"Phnom Kingdom\", is located near the mountains in Ba Phnom district, where only some traces remain today, such as an ancient temple called Prasat Chan, located in front of Wat Vihear Kuk, near the foot of Sampoev mountain in Cheung Phnom commune. Because there was war during Norkor Phnom era, departments and palaces were torn apart. The mountain has a beautiful view when we reach the top of the mountain and look down. There are large rocks and caves where can be habitats of wildlife. At the foot of the mountain, there is a pagoda named “Phnom pagoda” or “Ba Phnom pagoda”. Ba Phnom resort is a man-made resort. Trails were constructed to ease the travelling of tourists. The construction of the new temple has ancient sculptures surrounding the mountain with two stairs and hermitages.",
