    "descriptionEn": "Veal Prang is a natural tourist site in Prey Veng provincial town. Since the provincial town market is located along the bank of a lake, from there, one can see the vast lake field, which is a dry rice field. Many locals come here to relax, especially in the evenings where food is sold. If you want to see the bright yellow sunset, try to reach the top of the tower (Chong Porm) at sunset and you will be able to capture the view very well.",
