    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "ស្ពានអ្នកលឿង ដែលមានឈ្មោះថា ត្សឹបាសា មានប្រវែងជាង២គីឡូម៉ែត វែងជាងគេនៅប្រទេសកម្ពុជា ត្រូវបានដាក់ឱ្យប្រើប្រាស់តាំងពីឆ្នាំ ២០១៥មក។ ពាក្យថា ត្សឹបាសា ភាសាជប៉ុននេះ មាននយ័ជាភាសាខ្មែរថា ស្លាប។ ស្ពានអ្នកលឿង គឺជាប្រភេទស្ពានខ្សែកាបយោងទី១ធំជាងគេនៅកម្ពុជា ដែលបានចំណាយទឹកប្រាក់សាងសង់ ប្រមាណ ១២៧លានដុល្លារ ដែលជាថវិកាជំនួយឥតសំណងរបស់រដ្ឋាភិបាលជប៉ុន និងថវិកា ជាង ១៩លានដុល្លា របស់រដ្ឋាភិបាលកម្ពុជា។ ស្ពាននេះបានជួយដោះស្រាយបញ្ហាកកស្ទះចរាចរណ៍ដោយសារការរង់ចាំសាឡាងអ្នកលឿង ហើយត្រូវចំណាយពេលសាងសង់ដល់ទៅ ៤ឆ្នាំ។ ក្រៅពីតួស្ពានសុទ្ធសាធមានប្រវែងជាង ២គីឡូម៉ែត្រ និង ទទឹង១៣ម៉ែត្រមានផ្លូវតភ្ជាប់ ប្រវែងសរុប ៥៤០០ម៉ែត្រ។",
    "descriptionEn": "The Neak Leung Bridge, also known as Tsubasa, with a length of about two kilometers is the longest bridge in Cambodia and has been opening to public since 2015. The word ‘Tsubasa’ means ‘wings’ in Khmer. The Neak Leung Bridge is the first large cable-stayed bridges in Cambodia with the construction cost of 127 million dollars granted by Japan government, and more than 19 million dollars from the Royal Government of Cambodia. Since the bridge was opened to traffic, cars cross the Mekong River in five minutes, solving the problem of waiting long hours of ferry crossing. The t bridge is more than 2 kilometers long, and 13 meters width long, and including the attached road section, the total length is 5400 kilometers.",
