    "descriptionKh": "តំបន់កោះកេរមានចម្លាក់នៅលើផ្ទាំងថ្មធម្មជាតិជុំវិញត្រពាំងខ្នារដែលមានប្រភពមួយចំនួនមានទឹកធម្មជាតិហូរកាត់ និងមួយចំនួនលិចទឹកក្នុងរដូវវស្សា។ ត្រពាំងខ្នារស្ថិតនៅជិតប្រាសាទខ្នារមានទំហំ ២២x១៨០ម៉ែត្រ។ ត្រពាំងខ្នារឬត្រពាំងអង្គខ្នារជាត្រពាំងដែលគេជីកនិងដាប់ថ្មភក់ចេញរៀបចំជាត្រពាំង។ ចម្លាក់លើថ្មធម្មជាតិ និងបល្ល័ង្កលិង្គផ្សេងៗទៀតមានការសឹករិចរិលខ្លាំង តែមានចម្លាក់មួយចំនួននៅអាចសម្គាល់បាន។ ចម្លាក់ទាំងនេះមានរូបទេពសំខាន់ៗដូចជា រូបសិវៈលិង្គ, ឥសីទាំង៧ នព្វគ្រោះ និងរូបសត្វទេពផ្សេងៗទៀត។ ចម្លាក់តាមមាត់ត្រពាំងខ្នារនេះចែកជា៤ប្រភេទដូចជា ចម្លាក់សត្វមាន១០កន្លែង ចម្លាក់រូបទេពមាន១២កន្លែង ចម្លាក់រូបឥសីជាមួយទេពផ្សេងៗមាន១៣កន្លែង និងកន្លែងយកថ្មជាមួយចម្លាក់ខូចខាតមាន១១កន្លែង។",
    "descriptionEn": "Koh Ker has natural rock carvings around the Khnar pond, some of which have natural water flowing through them and some of which flood during the rainy season. Trapeang Khnar is located near Prasat Khnar, measuring 22x180 meters. Khnar pond or Ang Khnar pond is a pond that is dug and sandstone cut out and arranged as a pond. Natural stone carvings and other penises have been severely eroded, but some are still noticeable. These sculptures contain important deities such as Siva Ling, the seven auspicious idols, and other deities. The sculptures at the mouth of the Khnar pond are divided into four categories: 10 animal sculptures, 12 sculptures, 13 sculptures with various deities, and 11 stone carvings with damaged sculptures.",
