    "categoryEn": "Historical Temple / Heritage",
    "descriptionKh": "ប្រាសាទនេះកសាងក្នុងរជ្ជកាលព្រះបាទជ័យវរ្ម័នទី៤ នាសតវត្សរ៍ទី១០។ ប្រាសាទនេះស្ថិតនៅជាគូជិតប្រាសាទដំរី មានប្រាង្គទោលរាងបួងជ្រុងស្មើ ធ្វើអំពីថ្មបាយក្រៀម មានជណ្ដើរឡើងទាំងបួនទិស ទៅកាន់ទ្វារបញ្ឆោតលើកលែងតែជណ្ដើរខាងកើត មានទ្វារចូលក្នុងតួប្រាង្គតែម្ដង គឺប្រាសាទនេះបែរមុខទៅទិសខាងកើត។ ស៊ុមទ្វារអំពីថ្មភក់និងលំអដោយសសរពេជ្រប្រាំបីជ្រុង។ នៅលើទ្វារមានផ្ដែរសឹករិចរិលពិបាកមើលក៏ប៉ុន្តែការបញ្ជាក់ពីលោក ហង់រី ប៉ាម៉ង់ជេ បានបង្ហាញថា ផ្ដែរលំអដោយកម្រងមាលាជាក្បាច់ដងធ្នូ មានរូបព្រះឥន្ទ្រគង់លើដំរីក្បាលបីព្ធរាវ័ណ ជាទេពប្រចាំទិសខាងកើត ជាស្តេចនៃទេវៈទាំងឡាយនៃឋានត្រ័យត្រិង្សជាអ្នកបង្កើតទឹកភ្លៀងនិងផ្គររន្ទះ។",
    "descriptionEn": "This temple was built during the reign of Jayavarman IV in the 10th century. This temple is located in a pair near the Elephant Temple. It has a single tower with a square shape made of laterite. There are stairs in all four directions to the false door. Born. The door frame is made of sandstone and decorated with octagonal diamond pillars. On the door there are erosions that are difficult to see, but the confirmation of Henry Pamangje shows that the decoration is decorated with a series of ornaments in the form of a bow, with the image of Indra sitting on the three-headed elephant, the royal deity in the east, the king of the gods. Of the Trinity, the creator of rain and thunder.",
