    "descriptionEn": "The temple was built in the 10th century like other temples in the area. The Chen temple has three towers made of sandstone and laterite to dedicate to Shiva Hinduism. All three towers are in a dilapidated condition and have been restored. In front of the central tower, on the left side, at the entrance, there is an inscription with a long name of the temple servant. The temple has two brick huts facing the three towers. The three towers above have two walls and many lines of inscriptions. In these two entrances, many statues of the characters in the story of Ramayana (Reamker) and Mahabharata were kept, so the locals, who were supposed to be Chinese, also called Chinese temples. At the west entrance, there are nine statues that are the main characters in the story of the Great War.",
