    "descriptionKh": "ប្រាសាទកសាងឡើងនៅសតវត្សរ៍ទី១០ ដូចប្រាសាទដទៃក្នុងតំបន់នេះដែរ។ ប្រាសាទនេះគ្មានឈ្មោះដើមនៅក្នុងសិលាចារឹកឡើយ ទើបសម័យក្រោយមកនេះគេហៅថា ប្រាសាទច្រាបជាផ្លូវការជារៀងមក។ ដល់បច្ចុប្បន្ននេះ។ ប្រាសាទមានកំពែងការពារពីរជាន់ ធ្វើអំពីថ្មបាយក្រៀមដូចគ្នា ដោយកំពែងទី១ឬកំពែងខាងក្នុងរត់ជួរជើងទៅត្បូង បែរមុខទៅរកទិស ខាងលិចតាមស៊ុមទ្វារអំពីថ្មភក់។ ប្រាសាទនេះមានតួប្រាង្គបី ធ្វើអំពីថ្មបាយក្រៀមត្រូវរលុះអស់ពាក់កណ្ដាលផ្នែកខាងលិច និងមានតួប្រាង្គទាំងនេះលំអដោយទ្វារបញ្ឆោត។ ប្រាសាទសង់លើខឿនថ្មបាយក្រៀមតែមួយដោយមានជណ្ដើរបី និងមានហោត្រៃពីរ ដែលមួយស្ថាបនាឡើងដោយថ្មបានក្រៀម ឯមួយទៀតធ្វើអំពីឥដ្ឋ។",
    "descriptionEn": "The temple was built in the 10th century like other temples in the area. This temple does not have the original name in the inscription, so later it was officially called Prasat Chrab to this day. The temple has a double wall made of the same laterite, with the first wall or inner wall running north to south facing the sandstone door frame. The temple has three towers made of laterite, half of the western part, and these towers are decorated with false doors. The temple is built on a single laterite structure with three stairs and two hotspots, one built of laterite and the other made of brick.",
