    "descriptionEn": "The temple was built in the 10th century like other temples in the area. The temple has a square tower made of brick facing a sandstone door frame. The diamond pillars have an octagonal shape that supports one side and is adorned with a sliding door made of brick at the other corner. The tower is built on a sandstone ridge with stairs at all four corners. The roof of the tower is arranged in tiers and decorated with elephant statues at the corners of Khoeun and lions along the eastern staircase. The temple has two brick huts and a laterite wall adorned with sandstone slabs.",
