    "id": "rac-k18014",
    "nameKh": "ប្រាសាទនាងខ្មៅ (កោះកេរ)",
    "nameEn": "Neang Khmao Temple (Koh Ker)",
    "categorySlug": "temple",
    "categoryKh": "ប្រាសាទបុរាណ / បេតិកភណ្ឌ",
    "categoryEn": "Historical Temple / Heritage",
    "descriptionKh": "ប្រាសាទកសាងឡើងនៅសតវត្សរ៍ទី១០ ដូចប្រាសាទដទៃក្នុងតំបន់នេះដែរ។ ប្រាសាទនេះសាងសង់ដំណាលគ្នា ព្រមទាំងប្រកបដោយ រចនាបថដូចគ្នា នឹងប្រាសាទនាងខ្មៅនៅខេត្តតាកែវដែរ ហើយតាមរយៈឈ្មោះនេះ អ្នកខ្លះយល់ថាប្រាសាទប្រហែលជាឧទ្ទិសដល់ព្រះមហេសីមួយ របស់ព្រះឥសូរ ដែលមានសម្បុរខ្មៅគឺព្រះនាងកាលី។ ប៉ុន្តែមតិមួយទៀតយល់ថា ប្រហែលដោយសារសាច់ថ្មបាយក្រៀមនៅប្រាសាទនេះមានពណ៌ខ្មៅ ទើបហៅបែបនេះ។ ប្រាសាទនាងខ្មៅជាប្រាសាទទោលធ្វើពីថ្មបាយក្រៀម សង់លើខឿនថ្មបាយក្រៀម បែរមុខទៅទិសខាងលិច។ ស៊ុមទ្វារ សសរពេជ្រ និងផ្ដែរដែលសង់ពីថ្មភក់មានតែនៅច្រកទ្វារខាងលិចតែប៉ុណ្ណោះ។ ផ្ដែរស្ថិក្នុងរចនាបថកោះកេរ មានរូបព្រះព្រហ្មអង្គុយពែនភ្នែនលើផ្កាឈូក។ នៅខាងក្នុងមានតម្កល់លិង្គ និងស្នាទ្រោណិដែលធ្វើពីថ្មតែមួយដុំ។",
    "descriptionEn": "The temple was built in the 10th century like other temples in the area. This temple was built at the same time and has the same style as the Neang Khmao temple in Takeo province, and by this name, some people think that the temple may be dedicated to one of the dark-colored Iso goddesses, Princess Kali. But another opinion suggests that perhaps because the laterite in this temple is black, so called. Prasat Neang Khmao is a solitary temple made of laterite built on a laterite roof facing west. The sandstone door frame and pedestal are made of sandstone only at the west gate. In the Koh Ker style, there is a statue of Brahma sitting on a lotus flower. Inside, there is a penis and a stone pillar.",
