    "descriptionEn": "The temple was built in the 10th century like other temples in the area. Prasat Khnar has a body made of sandstone pieces erected together to form a large Shiva penis, 7 meters high, placed on a pedestal 5 meters high and about 6 meters wide. The temple has a drainage system to the north and is located on the west side at the axis with the Khnar pond about 100 meters. The sacred water that flows from the Khnar temple falls into the Khnar pond and drains. This temple has an open tower (or roof made of wood) which was built at the same time as the temple, between 928 AD.",
