    "categoryEn": "Historical Temple / Heritage",
    "descriptionKh": "ក្រុមប្រាសាទនេះដែលជាស្នាព្រះហស្ថរបស់ព្រះជ័យវរ្ម័នទី៤ នៅពាក់កណ្ដាលសតវត្សរ៍ទី១០។ ប្រាសាទដ៏សំខាន់ក្នុងបរិវេណនៃព្រះរាជធានីបុរាណមានឈ្មោះថា ឆោកគគីរ ដែលជាទីទួលមួយ ហើយសព្វថ្ងៃហៅថា កោះកេរ។ ប្រាសាទប្រាង្គធំជាប្រាសាទភ្នំ ដោយមានរាងជាសាជី មានកម្ពស់៣៥ម៉ែត្រ ចែកជា ៧ថ្នាក់ បែរមុខទៅទិសខាងលិច។ ប្រាសាទនេះត្រូវបានស្ថាបនាឡើងឧទ្ទិសចំពោះព្រះអាទិទេពត្រីភូវនេស្វរៈដែលជានាមមួយរបស់ព្រះសិវៈ។ ប្រាសាទ មានព្រះសិវលិង្គមួយធំសម្បើមដែលគេតម្កល់លើកំពូលប្រាសាទ។ ចម្លាក់នរសិង្ហធំៗ ស្ថិតក្នុងឥរិយាបទទ្រព្រះសិវលិង្គនោះ ប្រកបដោយមហិទ្ធិឫទ្ធិយ៉ាងសម្បើម ដែលគេឆ្លាក់មានក្បាលមួយដៃពីរមាត់ហារបញ្ចេញចង្កូមកំពុងសំដែងឫទ្ធិ។ គេបានប្រឌិតរឿងនិទាននាងកន្ទន់សត្រាឱ្យជាប់ទាក់ទងនិងប្រាសាទនេះ ហើយគេហៅកូនភ្នំមួយនៅជាប់នេះថាជាផ្នូរស្ដេចដំរីស ដែលការស្រាវជ្រាវបង្ហាញថាជាដីទួលសម្រាប់លើកថ្មសាងប្រាសាទនោះទេ។",
    "descriptionEn": "This group of temples, the work of Jayavarman IV in the middle of the 10th century. The main temple in the area of ​​the ancient capital is called Chok Koki, which is a hill and is now called Koh Ker. Prang Thom is a mountain temple with a conical shape, 35 meters high, divided into 7 levels, facing west. This temple was built dedicated to the god Tribhuvanesvara, one of the names of Shiva. The temple has a huge Sivaling that is placed on top of the temple. The huge lion statues in the posture of the Sivaling are very powerful, carved with one head, two hands, two mouths, revealing their fangs. The story of Kantan Satra was fabricated in connection with this temple, and a hill was called the Tomb of the Elephant King, which research shows is a hill for the stone to build the temple.",
