    "categoryEn": "Historical Temple / Heritage",
    "descriptionKh": "ប្រាសាទចិនស្រមកសាងឡើងនៅចុងសតវត្សរ៍ទី១០និងដើមសតវត្សរ៍ទី១១ ក្នុងរជ្ជកាលស្តេចបីអង្គគឺព្រះបាទជ័យវរ្ម័នទី៤ក្នុងរចនាបថកោះកេរ ព្រះបាទរាជេន្ទ្រវរ្ម័នក្នុងរចនាបថប្រែរូប និងព្រះបាទជ័យវរ្ម័នទី៥ ក្នុងរចនាបថបន្ទាយស្រី។ បន្ទាយចិនស្រមឬអ្នកស្រុកហៅថា «ប្រាសាទភូមិព្រៃវែង» មានកំពែង ៣ ជាន់ ធ្វើពីថ្មបាយក្រៀម កម្ពស់ ២,៥០ ម៉ែត្រ និង ២,២០ ម៉ែត្រ។ ចំណែកកំពែងទី៣ជាកំពែងដីទំហំ ១០០០x៦០០ ម៉ែត្រ។ ស្រះធំពីរជាបារាយណ៍នៅចម្ងាយជាង ៣០០ ម៉ែត្រពីប្រាសាទ។ ប្រាសាទនេះកសាងអំពីឥដ្ឋមានប្រាង្គប្រាំបែរមុខទៅទិសខាងកើតសង់នៅលើខឿនថ្មបាយក្រៀម មានបីថ្នាក់។ ប្រាសាទមានហោត្រៃចំនួនពីរសង់អំពីឥដ្ឋនិងសំណង់បន្ទប់រាងចតុកោណកែងចំនួនប្រាំបីសាងសង់អំពីថ្មភក់និងថ្មបាយក្រៀម ព្រមទាំងមានគោបុរៈចំនួនពីរនៅទិសខាងកើតនិងខាងលិច។ នៅជុំវិញប្រាង្គកណ្ដាលមានប្រាង្គតូចៗចំនួនបួនសង់នៅលើជ្រុងខឿននីមួយៗនៃជាន់ទី២។ ហោត្រៃទាំងពីរសាងសង់អំពីឥដ្ឋបែរមុខមកទិសខាងលិចនិងសំណង់បន្ទប់រាងចតុកោណកែងបានបាក់រលំអស់ភាគច្រើន។ គោបុរៈខាងកើត និងខាងលិចកសាងឡើងវិញអំពីថ្មភក់នៅក្នុងសរវត្សរ៍ទី១១ ដំណាល់គ្នានឹងតួប៉មកណ្ដាលដោយមានយកផ្ដែរសតវត្សរ៍ទី១០មកប្រើប្រាស់ឡើងវិញ។",
    "descriptionEn": "The Chinese temple was built in the late 10th and early 11th centuries during the reigns of three kings: Jayavarman IV in the Koh Ker style, Rajendravarman in the Transfiguration style, and Jayavarman V in the Banteay Srei style. Banteay Chen Srom, or as the locals call it, \"Prey Veng Temple\" has three floors of laterite walls, 2.50 meters high and 2.20 meters high. The third wall is a wall of land size 1000x600 meters. Two large ponds are barays more than 300 meters from the temple. The temple is built of brick, with five towers facing east, built on three levels of laterite. The temple has two brick huts and eight rectangular rooms built of sandstone and laterite, as well as two gopuras to the east and west. Around the central tower, there are four small towers built on each corner of the second floor. Both huts were built of brick facing west, and most of the rectangular rooms collapsed. The eastern and western gopuras were rebuilt of sandstone in the 11th century, simultaneously with the central tower, with re-use of the 10th century.",
    "photoUrl": "https://raw.githubusercontent.com/igpubinfo-max/Khmer-Food-Tourism/8d322f9/public/destinations/rac-k18031.jpg",
    "provinceKh": "ខេត្តព្រះវិហារ",
