    "descriptionKh": "ប្រាសាទនេះកសាងក្នុងរជ្ជកាលព្រះបាទរាជេន្ទ្រវរ្ម័នទី២ នាសតវត្សរ៍ទី១០។ ប្រាសាទសង់ពីឥដ្ឋមានកំពែងបីជាន់ដែលក្នុងកំពែងទីមួយធ្វើពីថ្មបាយក្រៀម មានខ្លោងទ្វារមួយធ្វើពីថ្មបាយក្រៀមច្រកទ្វារនៅខាងកើត។ ក្នុងកំពែងនេះមានប្រាង្គប្រាំធ្វើពីឥដ្ឋ និងសង់លើខឿនតែមួយ។ ប្រាង្គទាំងនេះរត់ជួរជើង-ត្បូងជាពីរជួរ បែរមុខទៅកើតតាមមេទ្វារថ្មភក់និងលំអដោយទ្វារបញ្ឆោតតាមជ្រុងផ្សេងទៀត។ ប្រាង្គកណ្ដាលមានយ៉ឥដ្ឋមួយលយចេញទៅខាងកើត។ ប្រាង្គទីប្រាំមួយស្ថិតនៅជ្រុងពាយ័ព្យ ហើយមានហោត្រៃពីរដែលមួយបាក់បែកធ្វើពីឥដ្ឋនៅអាគ្នេយ៍និងមួយទៀតធ្វើពីថ្មបាយក្រៀម។ កំពែងទីពីរធ្វើពីឥដ្ឋមានច្រកទ្វារតែមួយហើយមានគូទឹក ដែលមានគែមជាថ្មបាយក្រៀមរៀបជាថ្នាក់ៗ។ កំពែងទីបីមានអគារតូចៗពីរ ធ្វើពីឥដ្ឋស្ថិតនៅអមសងខាងបន្ទាត់ទ្រូងតជាប់ពីផ្នែកខាងក្រៅកំពែងទីពីរ។ ប្រាសាទនេះមានសិលាចារឹកជាច្រើនផងដែរ។",
    "descriptionEn": "This temple was built during the reign of King Rajendravarman II in the 10th century. The brick temple has three walls, the first of which is made of laterite and has a laterite gate on the east. Inside the ramparts are five brick towers built on a single block. These towers run in two rows, facing east through the main sandstone door and adorned with false doors at the other corners. The central tower has a brick balcony extending to the east. The sixth tower is on the northwest corner and has two huts, one of which is made of brick in the southeast and the other of laterite. The second brick wall had a single gate and a moat with laterite edges arranged in tiers. The third rampart consisted of two small brick buildings on either side of the chest line from the outside of the second rampart. The temple also has many inscriptions.",
