    "descriptionEn": "There is no document on the history of the construction of this temple. The temple has two towers facing each other, one made of sandstone and the other made of laterite. The laterite tower collapsed, leaving no trace, while the sandstone tower was decorated with false doors on the other three corners. The temple is surrounded by laterite walls and moats, as well as traces of ancient ponds.",
